window.SL_DATA.questions.push(
  { id:"PHY-Q051", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-9", type:"mcq", diff:"medium",
    q:{en:"A solid cylinder of mass 20 kg rotates about its axis at 100 rad/s. Its radius is 0.25 m. What is its rotational kinetic energy?", hi:"20 kg द्रव्यमान का ठोस बेलन अपनी अक्ष पर 100 rad/s से घूमता है। त्रिज्या 0.25 m है। उसकी घूर्णी गतिज ऊर्जा क्या है?"},
    opts:{en:["3125 J","6250 J","1562.5 J","625 J"],
          hi:["3125 J","6250 J","1562.5 J","625 J"]},
    correct:"A", exp:{en:"I = ½MR² = ½(20)(0.25)² = 0.625 kg m². K = ½Iω² = ½(0.625)(100)² = 3125 J.", hi:"I = ½MR² = ½(20)(0.25)² = 0.625 kg m²। K = ½Iω² = ½(0.625)(100)² = 3125 J।"},
    tags:["numerical","ncert-exercise","exam-important"], source:"NCERT Class 11 Physics, Ch 6 — Exercise 6.11", status:"published" },
  { id:"PHY-Q052", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-7", type:"short", diff:"medium",
    q:{en:"For that same 20 kg cylinder (R = 0.25 m, ω = 100 rad/s), the magnitude of its angular momentum about its axis is ____ J s.", hi:"उसी 20 kg बेलन के लिए (R = 0.25 m, ω = 100 rad/s), उसकी अक्ष के बारे में कोणीय संवेग का परिमाण ____ J s है।"},
    correct:"62.5|62.50", exp:{en:"L = Iω = 0.625 × 100 = 62.5 J s. NCERT quotes angular momentum in J s, which is the same as kg m²/s.", hi:"L = Iω = 0.625 × 100 = 62.5 J s। NCERT कोणीय संवेग J s में बताता है, जो kg m²/s के ही बराबर है।"},
    tags:["numerical","ncert-exercise"], source:"NCERT Class 11 Physics, Ch 6 — Exercise 6.11", status:"published" },
  { id:"PHY-Q053", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-10", type:"mcq", diff:"medium",
    q:{en:"A rope is wound round a hollow cylinder of mass 3 kg and radius 40 cm, and pulled with 30 N. What is the angular acceleration?", hi:"3 kg द्रव्यमान और 40 cm त्रिज्या के खोखले बेलन पर रस्सी लपेटकर 30 N से खींची जाती है। कोणीय त्वरण क्या है?"},
    opts:{en:["12 rad/s²","25 rad/s²","30 rad/s²","10 rad/s²"],
          hi:["12 rad/s²","25 rad/s²","30 rad/s²","10 rad/s²"]},
    correct:"B", exp:{en:"Hollow cylinder: I = MR² = 3(0.4)² = 0.48 kg m². τ = FR = 30(0.4) = 12 N m. α = τ/I = 12/0.48 = 25 rad/s².", hi:"खोखला बेलन: I = MR² = 3(0.4)² = 0.48 kg m²। τ = FR = 30(0.4) = 12 N m। α = τ/I = 12/0.48 = 25 rad/s²।"},
    tags:["numerical","ncert-exercise","exam-important"], source:"NCERT Class 11 Physics, Ch 6 — Exercise 6.13", status:"published" },
  { id:"PHY-Q054", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-10", type:"short", diff:"medium",
    q:{en:"In that same problem (α = 25 rad/s², R = 0.4 m), the linear acceleration of the rope is ____ m/s².", hi:"उसी प्रश्न में (α = 25 rad/s², R = 0.4 m), रस्सी का रेखीय त्वरण ____ m/s² है।"},
    correct:"10", exp:{en:"a = αR = 25 × 0.4 = 10 m/s². The rope does not slip, so its linear acceleration equals that of the rim.", hi:"a = αR = 25 × 0.4 = 10 m/s²। रस्सी फिसलती नहीं, इसलिए उसका रेखीय त्वरण किनारे के बराबर है।"},
    tags:["numerical","ncert-exercise"], source:"NCERT Class 11 Physics, Ch 6 — Exercise 6.13", status:"published" },
  { id:"PHY-Q055", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-10", type:"mcq", diff:"easy",
    q:{en:"An engine must keep a rotor at a steady 200 rad/s while delivering a torque of 180 N m. What power does it need?", hi:"एक engine को rotor 200 rad/s पर स्थिर रखना है और 180 N m का torque देना है। कितनी शक्ति चाहिए?"},
    opts:{en:["9 kW","36 kW","0.9 kW","72 kW"],
          hi:["9 kW","36 kW","0.9 kW","72 kW"]},
    correct:"B", exp:{en:"Rotational power P = τω = 180 × 200 = 36000 W = 36 kW.", hi:"घूर्णी शक्ति P = τω = 180 × 200 = 36000 W = 36 kW।"},
    tags:["numerical","ncert-exercise","exam-important"], source:"NCERT Class 11 Physics, Ch 6 — Exercise 6.14", status:"published" },
  { id:"PHY-Q056", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-10", type:"mcq", diff:"medium",
    q:{en:"A child on a frictionless turntable spins at 40 rev/min with arms out. He folds them, cutting his moment of inertia to 2/5 of its value. His new angular speed is:", hi:"घर्षण-रहित turntable पर बच्चा हाथ फैलाकर 40 rev/min से घूम रहा है। हाथ मोड़ने पर उसका जड़त्व आघूर्ण घटकर 2/5 रह जाता है। नया कोणीय वेग:"},
    opts:{en:["16 rev/min","40 rev/min","100 rev/min","250 rev/min"],
          hi:["16 rev/min","40 rev/min","100 rev/min","250 rev/min"]},
    correct:"C", exp:{en:"No external torque, so Iω is constant. I₂ = (2/5)I₁, hence ω₂ = ω₁(I₁/I₂) = 40 × (5/2) = 100 rev/min.", hi:"कोई बाहरी torque नहीं, तो Iω स्थिर है। I₂ = (2/5)I₁, इसलिए ω₂ = ω₁(I₁/I₂) = 40 × (5/2) = 100 rev/min।"},
    tags:["numerical","ncert-exercise","exam-important"], source:"NCERT Class 11 Physics, Ch 6 — Exercise 6.12(a)", status:"published" },
  { id:"PHY-Q057", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-8", type:"mcq", diff:"hard",
    q:{en:"A metre stick balances at its centre. Two coins of 5 g each are stacked at the 12.0 cm mark, and it now balances at 45.0 cm. The mass of the stick is:", hi:"एक मीटर छड़ अपने केंद्र पर संतुलित है। 5 g के दो सिक्के 12.0 cm पर रखे जाते हैं, और अब वह 45.0 cm पर संतुलित होती है। छड़ का द्रव्यमान:"},
    opts:{en:["33 g","66 g","110 g","150 g"],
          hi:["33 g","66 g","110 g","150 g"]},
    correct:"B", exp:{en:"Take moments about the new pivot at 45 cm. Coins (10 g) are 33 cm to the left; the stick's weight acts at its centre, 50 cm, i.e. 5 cm to the right. So 10 × 33 = M × 5, giving M = 66 g.", hi:"45 cm पर नए आधार के बारे में आघूर्ण लीजिए। सिक्के (10 g) बाईं ओर 33 cm पर; छड़ का भार उसके केंद्र 50 cm पर, यानी दाईं ओर 5 cm पर। तो 10 × 33 = M × 5, जिससे M = 66 g।"},
    tags:["numerical","ncert-exercise","hots","exam-important"], source:"NCERT Class 11 Physics, Ch 6 — Exercise 6.16", status:"published" },
  { id:"PHY-Q058", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-2", type:"mcq", diff:"medium",
    q:{en:"In HCl the nuclei are 1.27 Å apart, and chlorine is about 35.5 times as massive as hydrogen. The centre of mass lies approximately:", hi:"HCl में नाभिक 1.27 Å दूर हैं, और क्लोरीन हाइड्रोजन से लगभग 35.5 गुना भारी है। द्रव्यमान केन्द्र लगभग है:"},
    opts:{en:["0.635 Å from the H atom","1.24 Å from the H atom","1.24 Å from the Cl atom","At the midpoint"],
          hi:["H परमाणु से 0.635 Å","H परमाणु से 1.24 Å","Cl परमाणु से 1.24 Å","ठीक बीच में"]},
    correct:"B", exp:{en:"Put H at x = 0 and Cl at 1.27 Å. X = (1×0 + 35.5×1.27)/(1 + 35.5) = 45.085/36.5 ≈ 1.24 Å from the hydrogen — very close to the heavy chlorine nucleus.", hi:"H को x = 0 और Cl को 1.27 Å पर रखिए। X = (1×0 + 35.5×1.27)/(1 + 35.5) = 45.085/36.5 ≈ हाइड्रोजन से 1.24 Å — यानी भारी क्लोरीन नाभिक के बहुत पास।"},
    tags:["numerical","ncert-exercise","exam-important"], source:"NCERT Class 11 Physics, Ch 6 — Exercise 6.2", status:"published" },
  { id:"PHY-Q059", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-8", type:"mcq", diff:"hard",
    q:{en:"A 1800 kg car has its axles 1.8 m apart and its centre of gravity 1.05 m behind the front axle. Take g = 9.8 m/s². The force on EACH front wheel is:", hi:"1800 kg की कार के धुरे 1.8 m दूर हैं और गुरुत्व केन्द्र अगले धुरे से 1.05 m पीछे है। g = 9.8 m/s² लीजिए। *हर* अगले पहिये पर बल है:"},
    opts:{en:["3675 N","5145 N","7350 N","8820 N"],
          hi:["3675 N","5145 N","7350 N","8820 N"]},
    correct:"A", exp:{en:"W = 1800 × 9.8 = 17640 N. Moments about the front axle: (back pair) × 1.8 = W × 1.05, so the back pair carries 10290 N. Front pair = 17640 − 10290 = 7350 N, i.e. 3675 N per front wheel (and 5145 N per back wheel).", hi:"W = 1800 × 9.8 = 17640 N। अगले धुरे के बारे में आघूर्ण: (पिछली जोड़ी) × 1.8 = W × 1.05, तो पिछली जोड़ी 10290 N उठाती है। अगली जोड़ी = 17640 − 10290 = 7350 N, यानी हर अगले पहिये पर 3675 N (और हर पिछले पहिये पर 5145 N)।"},
    tags:["numerical","ncert-exercise","hots","exam-important"], source:"NCERT Class 11 Physics, Ch 6 — Exercise 6.9", status:"published" },
  { id:"PHY-Q060", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-2", type:"mcq", diff:"hard",
    q:{en:"From a uniform disc of radius R, a circular hole of radius R/2 is cut, its centre at R/2 from the disc's centre. The centre of gravity of the remaining body is at:", hi:"R त्रिज्या की एकसमान चकती से R/2 त्रिज्या का गोल छेद काटा जाता है, जिसका केंद्र चकती के केंद्र से R/2 पर है। बचे हिस्से का गुरुत्व केन्द्र है:"},
    opts:{en:["R/6 from the centre, on the side away from the hole","R/6 from the centre, on the hole's side","R/4 from the centre, away from the hole","Still at the centre"],
          hi:["केंद्र से R/6, छेद से दूर वाली ओर","केंद्र से R/6, छेद वाली ओर","केंद्र से R/4, छेद से दूर","अब भी केंद्र पर"]},
    correct:"A", exp:{en:"Treat the hole as negative mass. Mass ∝ area, so hole mass = M/4 and remaining = 3M/4. Taking the original centre as origin: 0 = (M/4)(R/2) + (3M/4)x, giving x = −R/6 — that is R/6 away from the hole.", hi:"छेद को ऋणात्मक द्रव्यमान मानिए। द्रव्यमान ∝ क्षेत्रफल, तो छेद = M/4 और बचा = 3M/4। मूल केंद्र को मूल बिंदु मानकर: 0 = (M/4)(R/2) + (3M/4)x, जिससे x = −R/6 — यानी छेद से R/6 दूर।"},
    tags:["numerical","ncert-exercise","hots","exam-important"], source:"NCERT Class 11 Physics, Ch 6 — Exercise 6.15", status:"published" },
  { id:"PHY-Q061", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-9", type:"mcq", diff:"hard",
    q:{en:"Equal torques act on a hollow cylinder and a solid sphere of the same mass and radius, about their own symmetry axes. After the same time, which has the greater angular speed?", hi:"एक ही द्रव्यमान और त्रिज्या के खोखले बेलन और ठोस गोले पर, उनकी अपनी सममिति अक्षों के बारे में, बराबर torque लगते हैं। उतने ही समय बाद किसका कोणीय वेग ज़्यादा होगा?"},
    opts:{en:["The hollow cylinder","The solid sphere","Both the same","Depends on the torque value"],
          hi:["खोखला बेलन","ठोस गोला","दोनों बराबर","torque के मान पर निर्भर"]},
    correct:"B", exp:{en:"α = τ/I, and ω = αt. Cylinder I = MR², sphere I = (2/5)MR². The sphere's smaller I gives a larger α, so after the same time it spins faster.", hi:"α = τ/I, और ω = αt। बेलन I = MR², गोला I = (2/5)MR²। गोले का छोटा I बड़ा α देता है, इसलिए उतने ही समय बाद वह तेज़ घूमेगा।"},
    tags:["ncert-exercise","compare-contrast","exam-important"], source:"NCERT Class 11 Physics, Ch 6 — Exercise 6.10", status:"published" },
  { id:"PHY-Q062", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-9", type:"mcq", diff:"easy",
    q:{en:"A ring, a disc and a solid sphere have the same mass and radius. About their central axes, which has the SMALLEST moment of inertia?", hi:"एक वलय, एक चकती और एक ठोस गोले का द्रव्यमान व त्रिज्या बराबर है। उनकी केंद्रीय अक्षों के बारे में सबसे *छोटा* जड़त्व आघूर्ण किसका है?"},
    opts:{en:["Ring (MR²)","Disc (½MR²)","Solid sphere (⅖MR²)","All equal"],
          hi:["वलय (MR²)","चकती (½MR²)","ठोस गोला (⅖MR²)","सब बराबर"]},
    correct:"C", exp:{en:"⅖ = 0.4 is less than ½ = 0.5 and less than 1. The sphere packs most of its mass close to the axis, where r² is small.", hi:"⅖ = 0.4, जो ½ = 0.5 और 1 दोनों से कम है। गोला अपना ज़्यादातर द्रव्यमान अक्ष के पास रखता है, जहाँ r² छोटा होता है।"},
    tags:["numerical","board-pattern","exam-important"], source:"Board-pattern numerical (direct application)", status:"published" },
  { id:"PHY-Q063", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-9", type:"short", diff:"easy",
    q:{en:"A flywheel has I = 2 kg m² and spins at 10 rad/s. Its rotational kinetic energy is ____ J.", hi:"एक flywheel का I = 2 kg m² है और वह 10 rad/s से घूमता है। उसकी घूर्णी गतिज ऊर्जा ____ J है।"},
    correct:"100", exp:{en:"K = ½Iω² = ½(2)(10)² = 100 J.", hi:"K = ½Iω² = ½(2)(10)² = 100 J।"},
    tags:["numerical","board-pattern"], source:"Board-pattern numerical (direct application)", status:"published" },
  { id:"PHY-Q064", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-10", type:"mcq", diff:"easy",
    q:{en:"A wheel at rest is given a constant angular acceleration of 3 rad/s². Its angular speed after 4 s is:", hi:"विराम में रखे पहिये को 3 rad/s² का स्थिर कोणीय त्वरण दिया जाता है। 4 s बाद उसका कोणीय वेग:"},
    opts:{en:["7 rad/s","12 rad/s","24 rad/s","0.75 rad/s"],
          hi:["7 rad/s","12 rad/s","24 rad/s","0.75 rad/s"]},
    correct:"B", exp:{en:"ω = ω₀ + αt = 0 + 3(4) = 12 rad/s.", hi:"ω = ω₀ + αt = 0 + 3(4) = 12 rad/s।"},
    tags:["numerical","board-pattern","exam-important"], source:"Board-pattern numerical (direct application)", status:"published" },
  { id:"PHY-Q065", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-10", type:"short", diff:"medium",
    q:{en:"A torque of 5 N m acts on a body of moment of inertia 0.5 kg m². The angular acceleration is ____ rad/s².", hi:"0.5 kg m² जड़त्व आघूर्ण वाली वस्तु पर 5 N m का torque लगता है। कोणीय त्वरण ____ rad/s² है।"},
    correct:"10", exp:{en:"τ = Iα, so α = τ/I = 5/0.5 = 10 rad/s².", hi:"τ = Iα, तो α = τ/I = 5/0.5 = 10 rad/s²।"},
    tags:["numerical","board-pattern"], source:"Board-pattern numerical (direct application)", status:"published" },
  { id:"PHY-Q066", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-8", type:"mcq", diff:"medium",
    q:{en:"On a see-saw, a 40 kg child sits 1.5 m from the pivot. A 60 kg child must sit at what distance on the other side to balance it?", hi:"See-saw पर 40 kg का बच्चा धुरी से 1.5 m दूर बैठा है। 60 kg के बच्चे को संतुलन के लिए दूसरी ओर कितनी दूर बैठना होगा?"},
    opts:{en:["0.5 m","1.0 m","2.0 m","2.25 m"],
          hi:["0.5 m","1.0 m","2.0 m","2.25 m"]},
    correct:"B", exp:{en:"Principle of moments: 40 × 1.5 = 60 × d, so d = 60/60 = 1.0 m. (g cancels from both sides.)", hi:"आघूर्ण का सिद्धांत: 40 × 1.5 = 60 × d, तो d = 60/60 = 1.0 m। (g दोनों ओर से कट जाता है।)"},
    tags:["numerical","board-pattern","exam-important"], source:"Board-pattern numerical (direct application)", status:"published" },
  { id:"PHY-Q067", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-5", type:"short", diff:"easy",
    q:{en:"A wheel turns at 120 rpm. In rad/s this is ____ (use π ≈ 3.14, give to 2 decimals).", hi:"एक पहिया 120 rpm पर घूमता है। rad/s में यह ____ है (π ≈ 3.14 लीजिए, 2 दशमलव तक)।"},
    correct:"12.56|12.57|4π", exp:{en:"ω = 2π × rpm/60 = 2π × 2 = 4π ≈ 12.56 rad/s.", hi:"ω = 2π × rpm/60 = 2π × 2 = 4π ≈ 12.56 rad/s।"},
    tags:["numerical","board-pattern"], source:"Board-pattern numerical (direct application)", status:"published" },
  { id:"PHY-Q068", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-9", type:"mcq", diff:"hard",
    q:{en:"Using the parallel axis theorem, the moment of inertia of a uniform rod of mass M and length L about an axis through one END, perpendicular to the rod, is:", hi:"समांतर अक्ष प्रमेय से, M द्रव्यमान और L लंबाई की एकसमान छड़ का, एक *सिरे* से गुज़रती और छड़ के लंबवत अक्ष के बारे में जड़त्व आघूर्ण है:"},
    opts:{en:["ML²/12","ML²/6","ML²/3","ML²/2"],
          hi:["ML²/12","ML²/6","ML²/3","ML²/2"]},
    correct:"C", exp:{en:"I_cm = ML²/12 and the end is d = L/2 away. I = I_cm + Md² = ML²/12 + M(L²/4) = ML²/12 + 3ML²/12 = ML²/3.", hi:"I_cm = ML²/12 और सिरा d = L/2 दूर है। I = I_cm + Md² = ML²/12 + M(L²/4) = ML²/12 + 3ML²/12 = ML²/3।"},
    tags:["numerical","jee-pattern","hots","exam-important"], source:"JEE-pattern numerical (multi-step)", status:"published" },
  { id:"PHY-Q069", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-9", type:"mcq", diff:"hard",
    q:{en:"A uniform disc of mass M and radius R. Its moment of inertia about a tangent lying IN its plane is:", hi:"M द्रव्यमान और R त्रिज्या की एकसमान चकती। उसके *तल में* स्थित स्पर्श रेखा के बारे में जड़त्व आघूर्ण है:"},
    opts:{en:["¾MR²","5/4 MR²","3/2 MR²","2MR²"],
          hi:["¾MR²","5/4 MR²","3/2 MR²","2MR²"]},
    correct:"B", exp:{en:"Two steps. Perpendicular axis theorem gives the diameter value: ½MR² = 2I_d, so I_d = ¼MR². Then parallel axis with d = R: I = ¼MR² + MR² = 5/4 MR².", hi:"दो चरण। लंबवत अक्ष प्रमेय से व्यास वाला मान: ½MR² = 2I_d, तो I_d = ¼MR²। फिर d = R के साथ समांतर अक्ष: I = ¼MR² + MR² = 5/4 MR²।"},
    tags:["numerical","jee-pattern","hots","exam-important"], source:"JEE-pattern numerical (multi-step)", status:"published" },
  { id:"PHY-Q070", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-9", type:"mcq", diff:"hard",
    q:{en:"A ring of mass M and radius R. Its moment of inertia about a tangent PERPENDICULAR to its plane is:", hi:"M द्रव्यमान और R त्रिज्या का वलय। उसके तल के *लंबवत* स्पर्श रेखा के बारे में जड़त्व आघूर्ण है:"},
    opts:{en:["MR²","3/2 MR²","2MR²","5/2 MR²"],
          hi:["MR²","3/2 MR²","2MR²","5/2 MR²"]},
    correct:"C", exp:{en:"About the central perpendicular axis, I = MR². A tangent perpendicular to the plane is parallel to it, a distance d = R away. So I = MR² + MR² = 2MR².", hi:"केंद्रीय लंबवत अक्ष के बारे में I = MR²। तल के लंबवत स्पर्श रेखा उसी के समांतर है, d = R दूरी पर। तो I = MR² + MR² = 2MR²।"},
    tags:["numerical","jee-pattern","hots","exam-important"], source:"JEE-pattern numerical (multi-step)", status:"published" },
  { id:"PHY-Q071", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-9", type:"mcq", diff:"hard",
    q:{en:"A solid sphere of mass M and radius R about a tangent line has moment of inertia:", hi:"M द्रव्यमान और R त्रिज्या के ठोस गोले का किसी स्पर्श रेखा के बारे में जड़त्व आघूर्ण है:"},
    opts:{en:["⅖MR²","7/5 MR²","3/2 MR²","2MR²"],
          hi:["⅖MR²","7/5 MR²","3/2 MR²","2MR²"]},
    correct:"B", exp:{en:"About a diameter I_cm = ⅖MR². A tangent is parallel to a diameter at d = R, so I = ⅖MR² + MR² = 7/5 MR².", hi:"व्यास के बारे में I_cm = ⅖MR²। स्पर्श रेखा किसी व्यास के समांतर d = R पर है, तो I = ⅖MR² + MR² = 7/5 MR²।"},
    tags:["numerical","jee-pattern","exam-important"], source:"JEE-pattern numerical (multi-step)", status:"published" },
  { id:"PHY-Q072", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-10", type:"mcq", diff:"hard",
    q:{en:"A flywheel of I = 0.5 kg m² starts from rest under a constant torque of 10 N m for 4 s. The work done by the torque is:", hi:"I = 0.5 kg m² का flywheel विराम से शुरू होकर 4 s तक 10 N m के स्थिर torque में चलता है। torque द्वारा किया गया कार्य है:"},
    opts:{en:["400 J","800 J","1600 J","3200 J"],
          hi:["400 J","800 J","1600 J","3200 J"]},
    correct:"C", exp:{en:"α = τ/I = 10/0.5 = 20 rad/s². θ = ½αt² = ½(20)(16) = 160 rad. W = τθ = 10 × 160 = 1600 J. Check: ω = αt = 80 rad/s, K = ½(0.5)(80)² = 1600 J — the work equals the kinetic energy gained.", hi:"α = τ/I = 10/0.5 = 20 rad/s²। θ = ½αt² = ½(20)(16) = 160 rad। W = τθ = 10 × 160 = 1600 J। जाँच: ω = αt = 80 rad/s, K = ½(0.5)(80)² = 1600 J — कार्य प्राप्त गतिज ऊर्जा के बराबर है।"},
    tags:["numerical","jee-pattern","hots","exam-important"], source:"JEE-pattern numerical (multi-step)", status:"published" },
  { id:"PHY-Q073", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-9", type:"mcq", diff:"hard",
    q:{en:"Two point masses of 2 kg each are fixed at the ends of a light rod of length 2 m. The radius of gyration about a perpendicular axis through the centre is:", hi:"2 m लंबी हल्की छड़ के सिरों पर 2 kg के दो बिंदु-द्रव्यमान लगे हैं। केंद्र से गुज़रती लंबवत अक्ष के बारे में परिभ्रमण त्रिज्या है:"},
    opts:{en:["0.5 m","1.0 m","1.41 m","2.0 m"],
          hi:["0.5 m","1.0 m","1.41 m","2.0 m"]},
    correct:"B", exp:{en:"Each mass is 1 m from the axis, so I = 2(1)² + 2(1)² = 4 kg m². Total M = 4 kg. From I = Mk²: 4 = 4k², so k = 1.0 m.", hi:"हर द्रव्यमान अक्ष से 1 m पर है, तो I = 2(1)² + 2(1)² = 4 kg m²। कुल M = 4 kg। I = Mk² से: 4 = 4k², तो k = 1.0 m।"},
    tags:["numerical","jee-pattern","hots"], source:"JEE-pattern numerical (multi-step)", status:"published" },
  { id:"PHY-Q074", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-10", type:"mcq", diff:"hard",
    q:{en:"A disc spinning at ω has a second identical disc (initially at rest) dropped coaxially onto it. They stick together. The final angular speed is:", hi:"ω से घूमती चकती पर वैसी ही दूसरी चकती (शुरू में विराम में) समाक्ष रूप से गिरा दी जाती है। वे चिपक जाती हैं। अंतिम कोणीय वेग है:"},
    opts:{en:["ω","ω/2","2ω","ω/4"],
          hi:["ω","ω/2","2ω","ω/4"]},
    correct:"B", exp:{en:"No external torque, so Iω is conserved. Initially Iω; finally the combined moment of inertia is 2I. So 2I·ω' = Iω, giving ω' = ω/2. (Kinetic energy is NOT conserved — half of it is lost to friction between the discs.)", hi:"कोई बाहरी torque नहीं, तो Iω संरक्षित है। शुरू में Iω; अंत में संयुक्त जड़त्व आघूर्ण 2I। तो 2I·ω' = Iω, यानी ω' = ω/2। (गतिज ऊर्जा संरक्षित *नहीं* — आधी चकतियों के बीच घर्षण में चली जाती है।)"},
    tags:["numerical","jee-pattern","hots","exam-important"], source:"JEE-pattern numerical (multi-step)", status:"published" },
  { id:"PHY-Q075", board:"CBSE", klass:"11", subject:"PHY", chapter:6, topic:"PHY-6-6", type:"mcq", diff:"hard",
    q:{en:"A force F = 3î + 2ĵ N acts at the point r = 2î + 4ĵ m. The torque about the origin is:", hi:"बल F = 3î + 2ĵ N, बिंदु r = 2î + 4ĵ m पर लगता है। मूल बिंदु के बारे में torque है:"},
    opts:{en:["8k̂ N m","−8k̂ N m","16k̂ N m","−16k̂ N m"],
          hi:["8k̂ N m","−8k̂ N m","16k̂ N m","−16k̂ N m"]},
    correct:"B", exp:{en:"τ = r × F = (2î + 4ĵ) × (3î + 2ĵ). Using î×ĵ = k̂ and ĵ×î = −k̂: (2)(2)(î×ĵ) + (4)(3)(ĵ×î) = 4k̂ − 12k̂ = −8k̂ N m. The minus sign means it turns clockwise as seen from +z.", hi:"τ = r × F = (2î + 4ĵ) × (3î + 2ĵ)। î×ĵ = k̂ और ĵ×î = −k̂ से: (2)(2)(î×ĵ) + (4)(3)(ĵ×î) = 4k̂ − 12k̂ = −8k̂ N m। ऋण चिह्न का मतलब +z से देखने पर घड़ी की दिशा में घुमाव।"},
    tags:["numerical","jee-pattern","hots","exam-important"], source:"JEE-pattern numerical (multi-step)", status:"published" }
);

