window.SL_DATA.questions.push(
  { id:"PHY-Q076", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-1", type:"mcq", diff:"easy",
    q:{en:"According to Kepler's law of orbits, a planet moves in:", hi:"केप्लर के कक्षाओं के नियम के अनुसार, ग्रह किसमें चलता है:"},
    opts:{en:["A circle with the Sun at the centre","An ellipse with the Sun at one focus","A straight line towards the Sun","A spiral that slowly shrinks"],
          hi:["वृत्त, सूर्य केंद्र पर","दीर्घवृत्त, सूर्य एक नाभि पर","सूर्य की ओर सीधी रेखा","धीरे-धीरे सिकुड़ता spiral"]},
    correct:"B", exp:{en:"The law of orbits states every planet moves in an ellipse with the Sun at one focus, not the centre — a circle is only the special case where both foci coincide.", hi:"कक्षाओं का नियम कहता है हर ग्रह दीर्घवृत्त में चलता है, सूर्य एक नाभि पर, केंद्र पर नहीं — वृत्त तो सिर्फ़ वह ख़ास हालत है जब दोनों नाभियाँ मिल जाएँ।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q077", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-1", type:"mcq", diff:"medium",
    q:{en:"A planet is at its closest point to the Sun (perihelion). According to the law of areas, its speed at this point is:", hi:"एक ग्रह सूर्य के सबसे पास वाले बिंदु (उपसौर) पर है। क्षेत्रफलों के नियम के अनुसार, इस बिंदु पर उसकी speed है:"},
    opts:{en:["Maximum for its orbit","Minimum for its orbit","Zero","Exactly equal to its speed at aphelion"],
          hi:["अपनी कक्षा के लिए अधिकतम","अपनी कक्षा के लिए न्यूनतम","शून्य","अपसौर पर की speed के ठीक बराबर"]},
    correct:"A", exp:{en:"Near the Sun the Sun-planet line is short, so to sweep equal area in equal time the planet must move through a longer arc quickly — speed is maximum at perihelion.", hi:"सूर्य के पास सूर्य-ग्रह रेखा छोटी है, तो समान समय में समान क्षेत्रफल बुहारने के लिए ग्रह को लंबा चाप तेज़ी से तय करना पड़ता है — उपसौर पर speed अधिकतम होती है।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q078", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-1", type:"tf", diff:"medium",
    q:{en:"A planet moving in an elliptical orbit around the Sun has constant speed throughout its orbit.", hi:"सूर्य के परित: दीर्घवृत्तीय कक्षा में चलता ग्रह अपनी पूरी कक्षा में स्थिर speed रखता है।"},
    correct:"FALSE", exp:{en:"Only in a perfect circular orbit is speed constant. In a real elliptical orbit, speed genuinely varies — fastest at perihelion, slowest at aphelion, by the law of areas.", hi:"सिर्फ़ बिलकुल गोल वृत्तीय कक्षा में speed स्थिर होती है। असली दीर्घवृत्तीय कक्षा में, speed सचमुच बदलती है — उपसौर पर सबसे तेज़, अपसौर पर सबसे धीमी, क्षेत्रफलों के नियम से।"},
    tags:["theory"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q079", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-1", type:"short", diff:"easy",
    q:{en:"Kepler's law of periods states that T² is proportional to a____ (fill in: which power of the semi-major axis a).", hi:"केप्लर का आवर्त कालों का नियम कहता है T², अर्ध-दीर्घ अक्ष a की a____ घात के अनुक्रमानुपाती है (सही घात भरिए)।"},
    correct:"3|cube|a3|a^3|घन", exp:{en:"T² ∝ a³ — the square of the period is proportional to the cube of the semi-major axis.", hi:"T² ∝ a³ — आवर्तकाल का वर्ग, अर्ध-दीर्घ अक्ष के घन के अनुक्रमानुपाती है।"},
    tags:["formula"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q080", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-1", type:"mcq", diff:"hard",
    q:{en:"A comet has a highly elongated elliptical orbit around the Sun. Which quantity remains constant throughout its orbit, even though its speed and distance from the Sun both change enormously?", hi:"एक धूमकेतु की सूर्य के परित: बहुत लंबी दीर्घवृत्तीय कक्षा है। कौन-सी राशि उसकी पूरी कक्षा में स्थिर रहती है, भले ही उसकी speed और सूर्य से दूरी दोनों बहुत बदलें?"},
    opts:{en:["Its linear speed","Its linear momentum","Its angular momentum about the Sun","Its kinetic energy"],
          hi:["उसकी रेखीय speed","उसका रेखीय संवेग","सूर्य के परित: उसका कोणीय संवेग","उसकी गतिज ऊर्जा"]},
    correct:"C", exp:{en:"Gravity is a central force on the comet, so it exerts zero torque about the Sun. With zero torque, angular momentum L is conserved throughout the orbit — this is exactly what produces the law of areas.", hi:"गुरुत्वाकर्षण धूमकेतु पर एक केंद्रीय बल है, तो सूर्य के परित: वह शून्य torque लगाता है। शून्य torque के साथ, कोणीय संवेग L पूरी कक्षा में संरक्षित रहता है — यही क्षेत्रफलों का नियम बनाता है।"},
    tags:["theory","hots","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q081", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-2", type:"mcq", diff:"easy",
    q:{en:"According to Newton's universal law of gravitation, the force between two point masses is proportional to:", hi:"न्यूटन के सार्वत्रिक गुरुत्वाकर्षण नियम के अनुसार, दो point masses के बीच बल किसके अनुक्रमानुपाती है:"},
    opts:{en:["m1 + m2, and r","m1 × m2, and 1/r","m1 × m2, and 1/r²","m1 × m2, and r²"],
          hi:["m1 + m2, और r","m1 × m2, और 1/r","m1 × m2, और 1/r²","m1 × m2, और r²"]},
    correct:"C", exp:{en:"F = Gm1m2/r² — directly proportional to the product of the masses, inversely proportional to the square of the distance.", hi:"F = Gm1m2/r² — द्रव्यमानों के गुणनफल के सीधे अनुक्रमानुपाती, दूरी के वर्ग के व्युत्क्रमानुपाती।"},
    tags:["formula","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q082", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-2", type:"mcq", diff:"medium",
    q:{en:"Three point masses pull on a fourth mass simultaneously. How is the net gravitational force on the fourth mass found?", hi:"तीन point masses एक साथ चौथे द्रव्यमान को खींचते हैं। चौथे द्रव्यमान पर शुद्ध गुरुत्वीय बल कैसे निकाला जाता है?"},
    opts:{en:["Add the three force magnitudes directly, ignoring direction","Take the average of the three forces","Add the three force vectors using the principle of superposition","Only the nearest mass's force counts"],
          hi:["तीनों बलों के परिमाण सीधे जोड़ दें, दिशा नज़रअंदाज़ करके","तीनों बलों का औसत लें","अध्यारोपण सिद्धांत से तीनों बल-vector जोड़ें","सिर्फ़ सबसे पास वाले द्रव्यमान का बल गिनें"]},
    correct:"C", exp:{en:"Each mass attracts independently; the principle of superposition says you sum the individual force vectors (magnitude and direction both) to get the resultant.", hi:"हर द्रव्यमान स्वतंत्र रूप से खींचता है; अध्यारोपण सिद्धांत कहता है परिणामी पाने के लिए हर बल-vector (परिमाण और दिशा दोनों) जोड़िए।"},
    tags:["theory"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q083", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-2", type:"tf", diff:"medium",
    q:{en:"A particle placed inside a uniform hollow spherical shell experiences zero net gravitational force from that shell.", hi:"किसी एकसमान खोखले गोलीय कोश के भीतर रखे कण पर उस कोश से शुद्ध गुरुत्वीय बल शून्य होता है।"},
    correct:"TRUE", exp:{en:"This is the shell theorem — pulls from every direction of a uniform shell cancel exactly for a point inside it.", hi:"यही कोश प्रमेय है — एकसमान कोश के भीतर के बिंदु के लिए हर दिशा से आने वाले खिंचाव बिलकुल कट जाते हैं।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q084", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-2", type:"short", diff:"easy",
    q:{en:"The SI unit of the universal gravitational constant G is N m² kg⁻____ (fill in the missing power).", hi:"सार्वत्रिक गुरुत्वीय स्थिरांक G का SI मात्रक N m² kg⁻____ है (गुम घात भरिए)।"},
    correct:"2", exp:{en:"G = 6.67×10⁻¹¹ N m² kg⁻². Two powers of kg in the denominator, one for each mass in F = Gm1m2/r².", hi:"G = 6.67×10⁻¹¹ N m² kg⁻². हर के दो घात kg के, F = Gm1m2/r² में हर द्रव्यमान के लिए एक।"},
    tags:["formula"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q085", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-2", type:"mcq", diff:"hard",
    q:{en:"Two identical uniform solid spheres, each of mass M and radius R, are far apart. Using the shell/sphere result, the gravitational force between them when their centres are a distance d apart (d >> R) is best modelled as:", hi:"दो एक जैसे एकसमान ठोस गोले, हर एक द्रव्यमान M और त्रिज्या R के, दूर-दूर हैं। कोश/गोला नतीजे का इस्तेमाल करते हुए, जब उनके केंद्र d दूरी पर हों (d >> R), उनके बीच गुरुत्वीय बल को सबसे अच्छा किस रूप में माना जाए:"},
    opts:{en:["Zero, since spheres are not point masses","GM²/d², treating each sphere as a point mass at its centre","GM²/R², independent of d","It cannot be calculated without calculus"],
          hi:["शून्य, क्योंकि गोले point masses नहीं हैं","GM²/d², हर गोले को उसके केंद्र पर point mass मानकर","GM²/R², d से स्वतंत्र","calculus के बिना निकाला ही नहीं जा सकता"]},
    correct:"B", exp:{en:"The shell theorem extends to uniform solid spheres too: outside a uniform sphere, it attracts exactly as if all its mass were concentrated at its centre. So F = GM²/d² is exact, not just an approximation, for any d ≥ the sum of the radii.", hi:"कोश प्रमेय एकसमान ठोस गोलों पर भी लागू होता है: एकसमान गोले के बाहर, वह ठीक ऐसे खींचता है जैसे उसका पूरा द्रव्यमान केंद्र पर हो। तो F = GM²/d² सटीक है, सिर्फ़ सन्निकटन नहीं, किसी भी d के लिए जो त्रिज्याओं के योग से बड़ा हो।"},
    tags:["theory","hots","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q086", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-3", type:"mcq", diff:"easy",
    q:{en:"The value of the universal gravitational constant G was first measured experimentally by:", hi:"सार्वत्रिक गुरुत्वीय स्थिरांक G का मान पहली बार प्रयोगात्मक रूप से किसने नापा:"},
    opts:{en:["Isaac Newton","Johannes Kepler","Henry Cavendish","Galileo Galilei"],
          hi:["आइज़क न्यूटन","जोहानेस केप्लर","हेनरी कैवेंडिश","गैलीलियो गैलीली"]},
    correct:"C", exp:{en:"Newton wrote the law but never measured G. Henry Cavendish measured it in 1798 using a torsion balance.", hi:"न्यूटन ने नियम लिखा पर G कभी नापा नहीं। हेनरी कैवेंडिश ने 1798 में मरोड़ तुला से इसे नापा।"},
    tags:["theory"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q087", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-3", type:"short", diff:"easy",
    q:{en:"The instrument Cavendish used to measure G is called a ____ balance.", hi:"G नापने के लिए कैवेंडिश ने जिस उपकरण का इस्तेमाल किया, उसे ____ तुला कहते हैं।"},
    correct:"torsion|मरोड़", exp:{en:"A torsion balance — a bar hanging from a fine wire, twisted by the tiny gravitational torque between small and large lead spheres.", hi:"मरोड़ तुला (torsion balance) — पतले तार से लटकी छड़, छोटे और बड़े सीसे के गोलों के बीच छोटे गुरुत्वीय torque से मुड़ती हुई।"},
    tags:["theory"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q088", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-3", type:"tf", diff:"medium",
    q:{en:"G and g mean the same thing and can be used interchangeably in any formula.", hi:"G और g एक ही चीज़ हैं और किसी भी formula में एक-दूसरे की जगह इस्तेमाल किए जा सकते हैं।"},
    correct:"FALSE", exp:{en:"G is the universal gravitational constant (same everywhere, 6.67×10⁻¹¹). g is the acceleration due to gravity, which depends on the planet and location: g = GM/R².", hi:"G सार्वत्रिक गुरुत्वीय स्थिरांक है (हर जगह वही, 6.67×10⁻¹¹)। g गुरुत्वीय त्वरण है, जो ग्रह और जगह पर निर्भर करता है: g = GM/R²।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q089", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-3", type:"mcq", diff:"medium",
    q:{en:"In Cavendish's experiment, at equilibrium, the gravitational torque on the suspended bar is balanced by:", hi:"कैवेंडिश के प्रयोग में, संतुलन पर, लटकी छड़ पर गुरुत्वीय torque किससे संतुलित होता है:"},
    opts:{en:["The weight of the small spheres","The restoring torque of the twisted wire","Air resistance on the bar","The magnetic field of the lead spheres"],
          hi:["छोटे गोलों का वज़न","मुड़े तार का restoring torque","छड़ पर हवा का प्रतिरोध","सीसे के गोलों का चुंबकीय क्षेत्र"]},
    correct:"B", exp:{en:"The fine wire twists and its restoring torque (proportional to twist angle θ) balances the small gravitational torque, at which point the twist angle can be measured and G calculated.", hi:"पतला तार मुड़ता है और उसका restoring torque (मरोड़ कोण θ के अनुक्रमानुपाती) छोटे गुरुत्वीय torque को संतुलित करता है, जिस बिंदु पर मरोड़ कोण नापा जा सकता है और G निकाला जा सकता है।"},
    tags:["theory"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q090", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-3", type:"mcq", diff:"hard",
    q:{en:"Why can an ordinary bathroom weighing scale never detect the gravitational pull between two people standing near each other, while Cavendish's apparatus could detect the pull between lead spheres?", hi:"साधारण बाथरूम का काँटा दो पास खड़े लोगों के बीच गुरुत्वीय खिंचाव कभी क्यों नहीं पकड़ पाता, जबकि कैवेंडिश का उपकरण सीसे के गोलों के बीच खिंचाव पकड़ लेता था?"},
    opts:{en:["People don't actually attract each other gravitationally","The scale measures weight (force from Earth), which completely swamps the tiny mutual pull; Cavendish's torsion balance was built specifically to cancel out larger forces and amplify a tiny torque","G is different for people than for lead","The scale is not sensitive enough to detect any force below 1 N, and this is a special case"],
          hi:["लोग असल में एक-दूसरे को गुरुत्वाकर्षण से खींचते ही नहीं","काँटा वज़न (पृथ्वी से बल) नापता है, जो छोटे परस्पर खिंचाव को पूरी तरह दबा देता है; कैवेंडिश की मरोड़ तुला ख़ास तौर पर बड़े बलों को रद्द कर एक छोटे torque को बढ़ाने के लिए बनी थी","लोगों के लिए G सीसे से अलग है","काँटा 1 N से कम किसी भी बल को पकड़ने लायक़ संवेदनशील नहीं, और यह ख़ास मामला है"]},
    correct:"B", exp:{en:"A bathroom scale is built to measure a large, constant background force (your weight from Earth) and cannot isolate the much tinier force between two nearby masses. Cavendish's torsion balance removed the large background entirely — the bar feels no net force, only a torque from the tiny mutual pull — letting a very small effect become measurable.", hi:"बाथरूम का काँटा एक बड़े, स्थिर पृष्ठभूमि बल (पृथ्वी से आपका वज़न) को नापने के लिए बना है और दो पास के द्रव्यमानों के बीच के कहीं छोटे बल को अलग नहीं कर सकता। कैवेंडिश की मरोड़ तुला ने बड़ी पृष्ठभूमि पूरी तरह हटा दी — छड़ पर कोई शुद्ध बल महसूस नहीं होता, सिर्फ़ छोटे परस्पर खिंचाव से एक torque — जिससे बहुत छोटा असर नापने लायक़ बन गया।"},
    tags:["theory","hots"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q091", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-4", type:"mcq", diff:"easy",
    q:{en:"The acceleration due to gravity g is maximum at:", hi:"गुरुत्वीय त्वरण g अधिकतम कहाँ होता है:"},
    opts:{en:["The centre of the Earth","Exactly at Earth's surface","At a height equal to Earth's radius","At a depth equal to half Earth's radius"],
          hi:["पृथ्वी के केंद्र पर","ठीक पृथ्वी की सतह पर","पृथ्वी की त्रिज्या के बराबर ऊँचाई पर","पृथ्वी की आधी त्रिज्या के बराबर गहराई पर"]},
    correct:"B", exp:{en:"g decreases both going up (height) and going down (depth) from the surface — the surface is the peak of the g-vs-distance graph.", hi:"g सतह से ऊपर (ऊँचाई) और नीचे (गहराई) दोनों ओर घटता है — सतह ही g-बनाम-दूरी graph की चोटी है।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q092", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-4", type:"mcq", diff:"medium",
    q:{en:"For the same distance moved (say 1 km), compared to descending into a mine, climbing the same distance up a mountain makes g:", hi:"बराबर दूरी तय करने पर (मान लीजिए 1 km), खदान में उतरने के मुक़ाबले, उतनी ही दूरी पहाड़ पर चढ़ने पर g:"},
    opts:{en:["Decrease by the same amount as descending","Decrease by roughly twice as much as descending","Decrease by roughly half as much as descending","Not change at all"],
          hi:["उतरने जितना ही घटता है","उतरने से लगभग दुगना घटता है","उतरने से लगभग आधा घटता है","बिलकुल नहीं बदलता"]},
    correct:"B", exp:{en:"g(h) ≈ g(1 − 2h/RE) for height, but g(d) = g(1 − d/RE) for depth. The factor 2 in the height formula means climbing costs roughly twice what descending the same distance does.", hi:"ऊँचाई के लिए g(h) ≈ g(1 − 2h/RE), पर गहराई के लिए g(d) = g(1 − d/RE)। ऊँचाई के formula में 2 का गुणक मतलब है चढ़ना उतनी ही दूरी उतरने से लगभग दुगना वसूलता है।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q093", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-4", type:"tf", diff:"medium",
    q:{en:"As you descend towards the centre of the Earth, g keeps increasing because you are getting closer to more mass.", hi:"पृथ्वी के केंद्र की ओर उतरते हुए, g बढ़ता रहता है क्योंकि आप ज़्यादा द्रव्यमान के पास पहुँच रहे हैं।"},
    correct:"FALSE", exp:{en:"g decreases as you descend, reaching zero at the very centre. Only the sphere of mass closer to the centre than you pulls on you (shell theorem), and that sphere shrinks as you go down.", hi:"उतरते हुए g घटता है, ठीक केंद्र पर शून्य हो जाता है। सिर्फ़ वह गोला जो आपसे केंद्र के ज़्यादा पास है आपको खींचता है (कोश प्रमेय), और नीचे जाने पर वह गोला सिकुड़ता है।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q094", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-4", type:"short", diff:"medium",
    q:{en:"The formula for acceleration due to gravity at depth d below Earth's surface is g(d) = g(1 − d/____).", hi:"पृथ्वी की सतह से d गहराई पर गुरुत्वीय त्वरण का formula है g(d) = g(1 − d/____)।"},
    correct:"RE|R_E|R|पृथ्वी की त्रिज्या", exp:{en:"g(d) = g(0)[1 − d/RE], where RE is Earth's radius.", hi:"g(d) = g(0)[1 − d/RE], जहाँ RE पृथ्वी की त्रिज्या है।"},
    tags:["formula"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q095", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-4", type:"mcq", diff:"hard",
    q:{en:"A body weighs 200 N on Earth's surface. Taking RE = 6400 km, approximately what will it weigh at a height of 64 km above the surface? (Use g(h) ≈ g(1 − 2h/RE).)", hi:"पृथ्वी की सतह पर एक वस्तु का वज़न 200 N है। RE = 6400 km मानते हुए, सतह से 64 km ऊँचाई पर लगभग उसका वज़न क्या होगा? (g(h) ≈ g(1 − 2h/RE) इस्तेमाल कीजिए।)"},
    opts:{en:["200 N (no change)","196 N","150 N","100 N"],
          hi:["200 N (कोई बदलाव नहीं)","196 N","150 N","100 N"]},
    correct:"B", exp:{en:"h/RE = 64/6400 = 0.01. So g(h) ≈ g(1 − 0.02) = 0.98g. Weight ≈ 200 × 0.98 = 196 N.", hi:"h/RE = 64/6400 = 0.01। तो g(h) ≈ g(1 − 0.02) = 0.98g। वज़न ≈ 200 × 0.98 = 196 N।"},
    tags:["numerical","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q096", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-5", type:"mcq", diff:"easy",
    q:{en:"The gravitational potential energy of a mass at distance r from Earth's centre, V(r) = −GMEm/r, is:", hi:"पृथ्वी के केंद्र से दूरी r पर किसी द्रव्यमान की गुरुत्वीय स्थितिज ऊर्जा, V(r) = −GMEm/r, है:"},
    opts:{en:["Always positive","Always negative for finite r, zero only at infinity","Always zero","Positive close to Earth, negative far away"],
          hi:["हमेशा धनात्मक","सीमित r के लिए हमेशा ऋणात्मक, सिर्फ़ अनंत पर शून्य","हमेशा शून्य","पृथ्वी के पास धनात्मक, दूर ऋणात्मक"]},
    correct:"B", exp:{en:"With V = 0 chosen at infinity, every finite point is closer than infinity, so gravity has done positive work pulling the mass in — its potential energy relative to infinity is negative.", hi:"अनंत पर V = 0 चुनने से, हर सीमित बिंदु अनंत से ज़्यादा पास है, तो गुरुत्वाकर्षण ने द्रव्यमान को अंदर खींचने में धनात्मक काम किया है — अनंत के सापेक्ष उसकी स्थितिज ऊर्जा ऋणात्मक है।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q097", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-5", type:"tf", diff:"medium",
    q:{en:"The formula PE = mgh gives the exact gravitational potential energy for any height h, however large.", hi:"PE = mgh formula किसी भी ऊँचाई h के लिए, चाहे वह कितनी भी बड़ी हो, सटीक गुरुत्वीय स्थितिज ऊर्जा देता है।"},
    correct:"FALSE", exp:{en:"mgh is only an approximation, valid when h is much smaller than Earth's radius, so that g can be treated as constant. For large h, use the exact V(r) = −GMEm/r.", hi:"mgh सिर्फ़ एक सन्निकटन है, तब सही जब h पृथ्वी की त्रिज्या से बहुत छोटा हो, ताकि g को स्थिर माना जा सके। बड़े h के लिए, सटीक V(r) = −GMEm/r इस्तेमाल कीजिए।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q098", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-5", type:"short", diff:"easy",
    q:{en:"By convention, gravitational potential energy V(r) is taken to be zero at r = ____.", hi:"परिपाटी से, गुरुत्वीय स्थितिज ऊर्जा V(r) को r = ____ पर शून्य माना जाता है।"},
    correct:"infinity|infinite|∞|anant|अनंत", exp:{en:"V is chosen to be zero at r = infinity, the point of maximum separation, so all finite-distance potential energies come out negative.", hi:"V को r = अनंत पर शून्य चुना जाता है, अधिकतम दूरी वाला बिंदु, तो हर सीमित-दूरी वाली स्थितिज ऊर्जा ऋणात्मक निकलती है।"},
    tags:["formula"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q099", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-5", type:"mcq", diff:"medium",
    q:{en:"Which has gravitational potential energy closer to zero — a satellite orbiting close to Earth's surface, or one orbiting far out near the Moon's distance?", hi:"किसकी गुरुत्वीय स्थितिज ऊर्जा शून्य के ज़्यादा पास है — पृथ्वी की सतह के पास परिक्रमा करता उपग्रह, या चाँद जैसी दूरी पर दूर परिक्रमा करता उपग्रह?"},
    opts:{en:["The one close to the surface","The one far out near the Moon's distance","Both are exactly equal","Cannot be determined without more data"],
          hi:["सतह के पास वाला","चाँद जैसी दूरी पर दूर वाला","दोनों बिलकुल बराबर","बिना और आँकड़ों के तय नहीं किया जा सकता"]},
    correct:"B", exp:{en:"V(r) = −GMEm/r grows (becomes less negative) as r increases, approaching zero as r → infinity. The far satellite, at larger r, has PE closer to zero.", hi:"V(r) = −GMEm/r, r बढ़ने पर बढ़ता है (कम ऋणात्मक होता है), r → अनंत पर शून्य के पास पहुँचता है। बड़े r पर दूर वाले उपग्रह की PE शून्य के ज़्यादा पास है।"},
    tags:["theory"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q100", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-5", type:"mcq", diff:"hard",
    q:{en:"Four identical point masses m are placed at the corners of a square of side l. What is the total gravitational potential energy of this system? (There are 4 side-pairs at distance l and 2 diagonal pairs at distance √2 l.)", hi:"चार एक जैसे point masses m एक l भुजा वाले वर्ग के कोनों पर रखे हैं। इस निकाय की कुल गुरुत्वीय स्थितिज ऊर्जा क्या है? (l दूरी पर 4 भुजा-युग्म और √2 l दूरी पर 2 विकर्ण-युग्म हैं।)"},
    opts:{en:["−4Gm²/l","−Gm²(4 + 2/√2)/l","−Gm²(4/l + √2/l)","−4√2 Gm²/l"],
          hi:["−4Gm²/l","−Gm²(4 + 2/√2)/l","−Gm²(4/l + √2/l)","−4√2 Gm²/l"]},
    correct:"B", exp:{en:"Sum −Gm²/r over all 6 pairs: 4 side-pairs give −4Gm²/l, 2 diagonal pairs give −2Gm²/(√2 l) = −√2 Gm²/l. Total = −Gm²(4 + √2)/l, which matches option B written as −Gm²(4 + 2/√2)/l since 2/√2 = √2.", hi:"सभी 6 युग्मों पर −Gm²/r जोड़िए: 4 भुजा-युग्म देते हैं −4Gm²/l, 2 विकर्ण-युग्म देते हैं −2Gm²/(√2 l) = −√2 Gm²/l। कुल = −Gm²(4 + √2)/l, जो विकल्प B से मेल खाता है −Gm²(4 + 2/√2)/l के रूप में, क्योंकि 2/√2 = √2।"},
    tags:["numerical","hots","ncert-example"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q101", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-6", type:"mcq", diff:"easy",
    q:{en:"The escape speed from Earth's surface is approximately:", hi:"पृथ्वी की सतह से पलायन चाल लगभग है:"},
    opts:{en:["1.12 km/s","11.2 km/s","112 km/s","2.3 km/s"],
          hi:["1.12 km/s","11.2 km/s","112 km/s","2.3 km/s"]},
    correct:"B", exp:{en:"vₑ = √(2gRE) ≈ 11.2 km/s for Earth. (2.3 km/s is the Moon's much smaller escape speed.)", hi:"पृथ्वी के लिए vₑ = √(2gRE) ≈ 11.2 km/s। (2.3 km/s चाँद की कहीं छोटी पलायन चाल है।)"},
    tags:["formula","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q102", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-6", type:"mcq", diff:"medium",
    q:{en:"A 1 kg stone and a 1000 kg satellite are both launched from Earth's surface. Their escape speeds are:", hi:"1 kg का पत्थर और 1000 kg का उपग्रह, दोनों पृथ्वी की सतह से छोड़े जाते हैं। उनकी पलायन चालें हैं:"},
    opts:{en:["Different — the heavier object needs a much higher speed","Different — the lighter object needs a much higher speed","Exactly the same, since mass cancels out of the escape speed formula","Impossible to compare without knowing their shapes"],
          hi:["अलग — भारी वस्तु को कहीं ज़्यादा speed चाहिए","अलग — हल्की वस्तु को कहीं ज़्यादा speed चाहिए","बिलकुल एक जैसी, क्योंकि पलायन चाल के formula से द्रव्यमान कट जाता है","आकार जाने बिना तुलना नामुमकिन"]},
    correct:"C", exp:{en:"vₑ = √(2gRE) — no mass term at all. Escape speed depends only on the planet, never on the mass of the object trying to escape (though a heavier object needs far more energy/fuel to reach that same speed).", hi:"vₑ = √(2gRE) — इसमें द्रव्यमान का कोई पद ही नहीं। पलायन चाल सिर्फ़ ग्रह पर निर्भर करती है, कभी पलायन करने वाली वस्तु के द्रव्यमान पर नहीं (हालाँकि भारी वस्तु को उसी speed तक पहुँचने में कहीं ज़्यादा ऊर्जा/ईंधन चाहिए)।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q103", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-6", type:"tf", diff:"medium",
    q:{en:"The Moon has no atmosphere partly because its escape speed is much smaller than Earth's.", hi:"चाँद पर वायुमंडल नहीं है, आंशिक रूप से इसलिए क्योंकि उसकी पलायन चाल पृथ्वी से कहीं छोटी है।"},
    correct:"TRUE", exp:{en:"The Moon's escape speed (≈2.3 km/s) is low enough that gas molecules at typical thermal speeds easily exceed it and drift away over time, so the Moon cannot retain an atmosphere.", hi:"चाँद की पलायन चाल (≈2.3 km/s) इतनी कम है कि सामान्य ऊष्मीय speed पर गैस के अणु उसे आसानी से पार कर लेते हैं और समय के साथ बहकर निकल जाते हैं, तो चाँद वायुमंडल थाम नहीं पाता।"},
    tags:["theory"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q104", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-6", type:"short", diff:"easy",
    q:{en:"The formula for escape speed in terms of g and Earth's radius RE is vₑ = √(2 × g × ____).", hi:"g और पृथ्वी की त्रिज्या RE के रूप में पलायन चाल का formula है vₑ = √(2 × g × ____)।"},
    correct:"RE|R_E|R", exp:{en:"vₑ = √(2gRE).", hi:"vₑ = √(2gRE)।"},
    tags:["formula"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q105", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-6", type:"mcq", diff:"hard",
    q:{en:"A body is projected from Earth's surface at exactly 2vₑ (twice the escape speed). Using energy conservation, its speed once it is very far from Earth is:", hi:"पृथ्वी की सतह से ठीक 2vₑ (पलायन चाल की दुगनी) पर एक वस्तु छोड़ी जाती है। ऊर्जा संरक्षण का इस्तेमाल करते हुए, पृथ्वी से बहुत दूर पहुँचने पर उसकी speed है:"},
    opts:{en:["2vₑ (unchanged)","vₑ","√3 × vₑ","4vₑ"],
          hi:["2vₑ (अपरिवर्तित)","vₑ","√3 × vₑ","4vₑ"]},
    correct:"C", exp:{en:"½m(2vₑ)² − GMEm/RE = ½mv²_far (energy conservation, using GMEm/RE = ½mvₑ²). So ½(4vₑ²) − ½vₑ² = ½v²_far, giving v²_far = 3vₑ², so v_far = √3 vₑ.", hi:"½m(2vₑ)² − GMEm/RE = ½mv²_दूर (ऊर्जा संरक्षण, GMEm/RE = ½mvₑ² इस्तेमाल करते हुए)। तो ½(4vₑ²) − ½vₑ² = ½v²_दूर, जिससे v²_दूर = 3vₑ², तो v_दूर = √3 vₑ।"},
    tags:["numerical","hots","ncert-example","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q106", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-7", type:"mcq", diff:"easy",
    q:{en:"A satellite stays in orbit around Earth because:", hi:"एक उपग्रह पृथ्वी की परिक्रमा में इसलिए टिका रहता है क्योंकि:"},
    opts:{en:["It has an engine constantly firing to hold it up","Gravity provides exactly the centripetal force needed to keep it turning in its curved path while it falls","It is beyond the reach of Earth's gravity","Air resistance balances gravity"],
          hi:["उसका इंजन उसे ऊपर टिकाए रखने के लिए लगातार चलता है","गुरुत्वाकर्षण ठीक उतना ही अभिकेन्द्र बल देता है जो गिरते हुए उसके मुड़े रास्ते को बनाए रखने के लिए चाहिए","वह पृथ्वी के गुरुत्वाकर्षण की पहुँच से बाहर है","हवा का प्रतिरोध गुरुत्वाकर्षण को संतुलित करता है"]},
    correct:"B", exp:{en:"A satellite is in continuous free fall, but moving sideways fast enough that the curved Earth's surface drops away at the same rate — gravity supplies exactly the centripetal force for that curved path.", hi:"उपग्रह लगातार मुक्त पतन में है, पर बग़ल में इतनी तेज़ी से चल रहा है कि गोल पृथ्वी की सतह उतनी ही दर से नीचे खिसकती है — गुरुत्वाकर्षण उस मुड़े रास्ते के लिए ठीक अभिकेन्द्र बल देता है।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q107", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-7", type:"mcq", diff:"medium",
    q:{en:"As a satellite's orbital height h increases, its orbital speed V:", hi:"उपग्रह की कक्षीय ऊँचाई h बढ़ने पर, उसकी कक्षीय speed V:"},
    opts:{en:["Increases","Decreases","Stays exactly the same","Increases then decreases"],
          hi:["बढ़ती है","घटती है","बिलकुल वही रहती है","पहले बढ़ती है फिर घटती है"]},
    correct:"B", exp:{en:"V = √[GME/(RE+h)] — as (RE+h) grows, V shrinks. Farther-out satellites move more slowly.", hi:"V = √[GME/(RE+h)] — (RE+h) बढ़ने पर, V सिकुड़ता है। दूर वाले उपग्रह धीमे चलते हैं।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q108", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-7", type:"tf", diff:"medium",
    q:{en:"An astronaut inside a very small orbiting spacecraft cannot detect gravity through any local experiment.", hi:"बहुत छोटे परिक्रमा करते अंतरिक्ष यान के अंदर एक अंतरिक्ष यात्री किसी स्थानीय प्रयोग से गुरुत्वाकर्षण पकड़ नहीं सकता।"},
    correct:"TRUE", exp:{en:"In a small spacecraft, every part is in free fall at essentially the same rate, so no relative force is detectable locally — this is a genuine NCERT Points to Ponder statement. (A very large spacecraft, though, could reveal small variations in g across its size.)", hi:"छोटे यान में, हर हिस्सा लगभग एक ही दर से मुक्त पतन में है, तो स्थानीय रूप से कोई सापेक्ष बल पकड़ में नहीं आता — यह असली NCERT विचारणीय विषय कथन है। (बहुत बड़ा यान, हालाँकि, अपने आकार में g के छोटे बदलाव दिखा सकता है।)"},
    tags:["theory"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q109", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-7", type:"short", diff:"medium",
    q:{en:"The orbital period T and orbit radius r of a satellite are related by T² ∝ r____ (fill in the power) — this is Kepler's law of periods applied to satellites.", hi:"उपग्रह का कक्षीय आवर्तकाल T और कक्षा त्रिज्या r के बीच संबंध है T² ∝ r____ (घात भरिए) — यह उपग्रहों पर लागू केप्लर का आवर्त कालों का नियम है।"},
    correct:"3|cube|घन", exp:{en:"T² ∝ r³, the same relationship Kepler found for planets, derived here from Newton's law for any satellite.", hi:"T² ∝ r³, वही संबंध जो केप्लर ने ग्रहों के लिए पाया, यहाँ न्यूटन के नियम से किसी भी उपग्रह के लिए निकाला गया।"},
    tags:["formula"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q110", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-7", type:"mcq", diff:"hard",
    q:{en:"Io, one of Jupiter's satellites, has an orbital period of 1.769 days and orbital radius 4.22×10⁸ m. Using T² = (4π²/GMJ)R³, the mass of Jupiter works out to approximately:", hi:"Io, बृहस्पति का एक उपग्रह, का कक्षीय आवर्तकाल 1.769 दिन और कक्षीय त्रिज्या 4.22×10⁸ m है। T² = (4π²/GMJ)R³ का इस्तेमाल करके, बृहस्पति का द्रव्यमान लगभग निकलता है:"},
    opts:{en:["1.9 × 10²⁷ kg","6.0 × 10²⁴ kg","2.0 × 10³⁰ kg","4.2 × 10²³ kg"],
          hi:["1.9 × 10²⁷ kg","6.0 × 10²⁴ kg","2.0 × 10³⁰ kg","4.2 × 10²³ kg"]},
    correct:"A", exp:{en:"MJ = 4π²R³/(GT²). T = 1.769 × 24 × 3600 ≈ 1.53×10⁵ s. R³ = (4.22×10⁸)³ ≈ 7.51×10²⁵ m³. MJ = 4π² × 7.51×10²⁵ / (6.67×10⁻¹¹ × (1.53×10⁵)²) ≈ 1.9×10²⁷ kg — this is NCERT Exercise 7.4's setup, confirming Jupiter's mass is about 1000 times Earth's.", hi:"MJ = 4π²R³/(GT²)। T = 1.769 × 24 × 3600 ≈ 1.53×10⁵ s। R³ = (4.22×10⁸)³ ≈ 7.51×10²⁵ m³। MJ = 4π² × 7.51×10²⁵ / (6.67×10⁻¹¹ × (1.53×10⁵)²) ≈ 1.9×10²⁷ kg — यही NCERT अभ्यास 7.4 का सेटअप है, जो पुष्टि करता है बृहस्पति का द्रव्यमान पृथ्वी से लगभग 1000 गुना है।"},
    tags:["numerical","ncert-exercise","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q111", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-8", type:"mcq", diff:"easy",
    q:{en:"A geostationary satellite has an orbital period of:", hi:"भूस्थिर उपग्रह का कक्षीय आवर्तकाल है:"},
    opts:{en:["85 minutes","12 hours","24 hours","27.3 days"],
          hi:["85 मिनट","12 घंटे","24 घंटे","27.3 दिन"]},
    correct:"C", exp:{en:"A geostationary satellite's period exactly matches Earth's rotation period, 24 hours, so it appears fixed over one point on the equator.", hi:"भूस्थिर उपग्रह का आवर्तकाल पृथ्वी के घूर्णन काल, 24 घंटे, से ठीक मेल खाता है, तो वह भूमध्य रेखा पर एक बिंदु पर स्थिर दिखता है।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q112", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-8", type:"mcq", diff:"medium",
    q:{en:"For a satellite to appear stationary from the ground, which of the following is/are required?", hi:"किसी उपग्रह को ज़मीन से स्थिर दिखने के लिए, निम्न में से क्या ज़रूरी है/हैं?"},
    opts:{en:["Only a 24-hour period, altitude doesn't matter","24-hour period AND orbit in the equatorial plane AND same direction as Earth's spin, all three together","Only that it orbits above the equator","Only that it moves opposite to Earth's spin"],
          hi:["सिर्फ़ 24-घंटे का आवर्तकाल, ऊँचाई मायने नहीं रखती","24-घंटे का आवर्तकाल, भूमध्यरेखीय तल में कक्षा, और पृथ्वी के घूर्णन जैसी दिशा — तीनों साथ","सिर्फ़ यह कि वह भूमध्य रेखा के ऊपर परिक्रमा करे","सिर्फ़ यह कि वह पृथ्वी के घूर्णन के उल्टा चले"]},
    correct:"B", exp:{en:"All three conditions must hold together — matching period alone (any inclined or retrograde orbit with T=24h) would still drift across the sky daily.", hi:"तीनों शर्तें साथ चाहिए — अकेले सही आवर्तकाल (झुकी या उल्टी दिशा वाली कक्षा जिसका T=24h हो) भी रोज़ आकाश में बहती रहेगी।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q113", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-8", type:"tf", diff:"medium",
    q:{en:"All weather and remote-sensing satellites are geostationary.", hi:"सारे मौसम और सुदूर संवेदन उपग्रह भूस्थिर होते हैं।"},
    correct:"FALSE", exp:{en:"Many weather and remote-sensing satellites (like India's Cartosat and RISAT series) use much lower polar orbits, sweeping over the entire Earth as it rotates beneath, rather than watching one fixed patch from geostationary altitude.", hi:"कई मौसम और सुदूर संवेदन उपग्रह (जैसे भारत के Cartosat और RISAT series) कहीं नीची ध्रुवीय कक्षाओं का इस्तेमाल करते हैं, नीचे घूमती पूरी पृथ्वी को बुहारते हुए, भूस्थिर ऊँचाई से एक तय हिस्सा देखते रहने के बजाय।"},
    tags:["theory"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q114", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-8", type:"short", diff:"medium",
    q:{en:"The approximate altitude of a geostationary satellite above Earth's surface is about ____ km.", hi:"भूस्थिर उपग्रह की पृथ्वी की सतह से लगभग ऊँचाई ____ km है।"},
    correct:"35800|35786|35700|35900|36000", exp:{en:"About 35,800 km above the surface (roughly 42,200 km from Earth's centre), found by applying T² ∝ (RE+h)³ with T = 24 hours.", hi:"सतह से लगभग 35,800 km ऊपर (पृथ्वी के केंद्र से लगभग 42,200 km), T² ∝ (RE+h)³ को T = 24 घंटे के साथ लगाकर पाया गया।"},
    tags:["formula","numerical"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q115", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-8", type:"mcq", diff:"hard",
    q:{en:"A satellite is placed at exactly the geostationary altitude and correct period, but its orbital plane is tilted 15° from the equator. What will a fixed ground dish observe?", hi:"एक उपग्रह ठीक भूस्थिर ऊँचाई और सही आवर्तकाल पर रखा गया है, पर उसका कक्षीय तल भूमध्य रेखा से 15° झुका है। ज़मीन पर लगी स्थिर डिश क्या देखेगी?"},
    opts:{en:["The satellite will appear perfectly fixed, since period and altitude are correct","The satellite will drift north-south across the sky once per day, tracing a figure roughly like a figure-8 or straight line, even though its period matches Earth's rotation","The satellite will fall out of orbit","The satellite will appear to move east-west only"],
          hi:["उपग्रह बिलकुल स्थिर दिखेगा, क्योंकि आवर्तकाल और ऊँचाई सही हैं","उपग्रह रोज़ एक बार आकाश में उत्तर-दक्षिण बहेगा, लगभग figure-8 या सीधी रेखा जैसा आकार बनाते हुए, भले ही उसका आवर्तकाल पृथ्वी के घूर्णन से मेल खाता हो","उपग्रह कक्षा से गिर जाएगा","उपग्रह सिर्फ़ पूर्व-पश्चिम चलता दिखेगा"]},
    correct:"B", exp:{en:"Matching period alone is not sufficient — an inclined orbit still carries the satellite north and south of the equator once per orbit, so from the ground it traces a small daily loop (often called an 'analemma'-like figure) rather than staying at one fixed point.", hi:"अकेला सही आवर्तकाल काफ़ी नहीं — झुकी कक्षा उपग्रह को हर परिक्रमा में भूमध्य रेखा के उत्तर-दक्षिण ले जाती है, तो ज़मीन से वह एक छोटा दैनिक लूप (अक्सर 'analemma' जैसा आकार) बनाता दिखता है, एक तय बिंदु पर टिकने के बजाय।"},
    tags:["theory","hots"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q116", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-9", type:"mcq", diff:"easy",
    q:{en:"For a satellite in a stable circular orbit, the total mechanical energy E is:", hi:"स्थिर वृत्तीय कक्षा में उपग्रह के लिए, कुल यांत्रिक ऊर्जा E है:"},
    opts:{en:["Always positive","Always zero","Always negative","Sometimes positive, sometimes negative"],
          hi:["हमेशा धनात्मक","हमेशा शून्य","हमेशा ऋणात्मक","कभी धनात्मक, कभी ऋणात्मक"]},
    correct:"C", exp:{en:"E = −GMEm/2r is always negative for a bound circular orbit — this is what keeps the satellite gravitationally trapped.", hi:"बद्ध वृत्तीय कक्षा के लिए E = −GMEm/2r हमेशा ऋणात्मक होती है — यही उपग्रह को गुरुत्वाकर्षण से क़ैद रखती है।"},
    tags:["formula","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q117", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-9", type:"mcq", diff:"medium",
    q:{en:"For a satellite in circular orbit, how does the magnitude of potential energy compare to kinetic energy?", hi:"वृत्तीय कक्षा में उपग्रह के लिए, स्थितिज ऊर्जा का परिमाण गतिज ऊर्जा से कैसे तुलना करता है?"},
    opts:{en:["|P.E.| = K","|P.E.| = 2K","|P.E.| = K/2","|P.E.| = 4K"],
          hi:["|P.E.| = K","|P.E.| = 2K","|P.E.| = K/2","|P.E.| = 4K"]},
    correct:"B", exp:{en:"K = GMEm/2r and P.E. = −GMEm/r, so |P.E.| = GMEm/r = 2 × (GMEm/2r) = 2K.", hi:"K = GMEm/2r और P.E. = −GMEm/r, तो |P.E.| = GMEm/r = 2 × (GMEm/2r) = 2K।"},
    tags:["formula","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q118", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-9", type:"tf", diff:"medium",
    q:{en:"A higher orbit (larger r) has a total energy E that is more negative than a lower orbit's.", hi:"ऊँची कक्षा (बड़ा r) की कुल ऊर्जा E, नीची कक्षा से ज़्यादा ऋणात्मक होती है।"},
    correct:"FALSE", exp:{en:"E = −GMEm/2r. As r grows, the magnitude GMEm/2r shrinks, so E becomes LESS negative (closer to zero), not more negative, at higher orbits.", hi:"E = −GMEm/2r। r बढ़ने पर, परिमाण GMEm/2r सिकुड़ता है, तो ऊँची कक्षाओं पर E कम ऋणात्मक होती है (शून्य के पास), ज़्यादा ऋणात्मक नहीं।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q119", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-9", type:"short", diff:"medium",
    q:{en:"For an elliptical bound orbit, the total energy formula E = −GMm/2r generalises by replacing r with the ____ of the ellipse.", hi:"दीर्घवृत्तीय बद्ध कक्षा के लिए, कुल ऊर्जा का formula E = −GMm/2r, r की जगह दीर्घवृत्त का ____ रखकर सामान्यीकृत होता है।"},
    correct:"semi-major axis|semimajor axis|अर्ध-दीर्घ अक्ष|semi major axis", exp:{en:"E = −GMm/2a, where a is the semi-major axis. This works for any closed (bound) orbit, circular or elliptical.", hi:"E = −GMm/2a, जहाँ a अर्ध-दीर्घ अक्ष है। यह किसी भी बंद (बद्ध) कक्षा, वृत्तीय या दीर्घवृत्तीय, के लिए काम करता है।"},
    tags:["formula","jee-pattern"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q120", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-9", type:"mcq", diff:"hard",
    q:{en:"A 400 kg satellite is in a circular orbit of radius 2RE about the Earth. How much energy is required to transfer it to a circular orbit of radius 4RE? (This is NCERT Example 7.8's exact setup.)", hi:"400 kg का एक उपग्रह पृथ्वी के परित: 2RE त्रिज्या की वृत्तीय कक्षा में है। उसे 4RE त्रिज्या की वृत्तीय कक्षा में ले जाने के लिए कितनी ऊर्जा चाहिए? (यह NCERT उदाहरण 7.8 का बिलकुल वही सेटअप है।)"},
    opts:{en:["ΔE = GMEm/(8RE), a positive energy input is needed since Ef > Ei (Ef is less negative)","ΔE = 0, since both are bound circular orbits","ΔE = −GMEm/(8RE), energy must be removed","ΔE = GMEm/(2RE)"],
          hi:["ΔE = GMEm/(8RE), धनात्मक ऊर्जा चाहिए क्योंकि Ef > Ei (Ef कम ऋणात्मक है)","ΔE = 0, क्योंकि दोनों बद्ध वृत्तीय कक्षाएँ हैं","ΔE = −GMEm/(8RE), ऊर्जा निकालनी होगी","ΔE = GMEm/(2RE)"]},
    correct:"A", exp:{en:"Ei = −GMEm/(4RE), Ef = −GMEm/(8RE). ΔE = Ef − Ei = −GMEm/8RE − (−GMEm/4RE) = GMEm/8RE, a positive quantity — raising a satellite to a higher orbit always requires adding energy, even though its kinetic energy and speed actually decrease.", hi:"Ei = −GMEm/(4RE), Ef = −GMEm/(8RE)। ΔE = Ef − Ei = −GMEm/8RE − (−GMEm/4RE) = GMEm/8RE, एक धनात्मक राशि — उपग्रह को ऊँची कक्षा में ले जाने में हमेशा ऊर्जा जोड़नी पड़ती है, भले ही उसकी गतिज ऊर्जा और speed असल में घटें।"},
    tags:["numerical","ncert-example","hots","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q121", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-10", type:"mcq", diff:"easy",
    q:{en:"Astronauts on the ISS feel weightless mainly because:", hi:"ISS पर अंतरिक्ष यात्री मुख्य रूप से इसलिए भारहीन महसूस करते हैं क्योंकि:"},
    opts:{en:["Gravity is essentially zero at that altitude","They and their spacecraft are in continuous free fall together, so there is no floor push on them","There is no air resistance in space","Their training removes their sense of weight"],
          hi:["उस ऊँचाई पर गुरुत्वाकर्षण लगभग शून्य है","वे और उनका यान साथ लगातार मुक्त पतन में हैं, तो उन पर कोई फ़र्श का धक्का नहीं लगता","अंतरिक्ष में हवा का प्रतिरोध नहीं होता","उनकी training उनका वज़न महसूस करने का एहसास हटा देती है"]},
    correct:"B", exp:{en:"Gravity at ISS altitude is still about 90% of surface value. Weightlessness comes from continuous free fall — no relative push between astronaut and spacecraft floor.", hi:"ISS की ऊँचाई पर गुरुत्वाकर्षण अब भी सतह के मान का लगभग 90% है। भारहीनता लगातार मुक्त पतन से आती है — अंतरिक्ष यात्री और यान के फ़र्श के बीच कोई सापेक्ष धक्का नहीं।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q122", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-10", type:"tf", diff:"medium",
    q:{en:"Weight, as felt by a person, is the same thing as the gravitational force acting on them.", hi:"किसी व्यक्ति द्वारा महसूस किया गया वज़न, उस पर लगे गुरुत्वीय बल जैसी ही चीज़ है।"},
    correct:"FALSE", exp:{en:"Felt weight is the contact/normal force the floor pushes back with, resisting gravity. In free fall, gravity still acts fully, but the contact force (and so felt weight) drops to zero.", hi:"महसूस किया गया वज़न वह संपर्क/normal बल है जो फ़र्श गुरुत्वाकर्षण का विरोध करते हुए वापस लगाता है। मुक्त पतन में, गुरुत्वाकर्षण पूरी तरह काम करता रहता है, पर संपर्क बल (और इसलिए महसूस वज़न) शून्य हो जाता है।"},
    tags:["theory","exam-important"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q123", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-10", type:"short", diff:"easy",
    q:{en:"Astronauts and their spacecraft feel weightless because both are in continuous ____ towards Earth.", hi:"अंतरिक्ष यात्री और उनका यान भारहीन महसूस करते हैं क्योंकि दोनों पृथ्वी की ओर लगातार ____ में हैं।"},
    correct:"free fall|freefall|मुक्त पतन", exp:{en:"Continuous free fall — moving sideways fast enough to keep missing the ground as they fall.", hi:"लगातार मुक्त पतन — गिरते हुए बग़ल में इतनी तेज़ चलना कि ज़मीन को हमेशा चूकते रहें।"},
    tags:["theory"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q124", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-10", type:"mcq", diff:"medium",
    q:{en:"Which of these situations does NOT involve the free-fall explanation of weightlessness?", hi:"इनमें से कौन-सी स्थिति में भारहीनता की मुक्त-पतन वाली व्याख्या लागू नहीं होती?"},
    opts:{en:["A satellite orbiting Earth","A lift whose cable has snapped, falling freely","An astronaut floating inside the ISS","A person standing still on a weighing scale on solid ground"],
          hi:["पृथ्वी की परिक्रमा करता उपग्रह","एक लिफ़्ट जिसका तार टूट गया, मुक्त रूप से गिरती हुई","ISS के अंदर तैरता एक अंतरिक्ष यात्री","ठोस ज़मीन पर तराज़ू पर स्थिर खड़ा व्यक्ति"]},
    correct:"D", exp:{en:"A person standing on solid ground is not in free fall — the ground pushes back with a normal force equal to their weight, so they feel their full weight, not weightlessness.", hi:"ठोस ज़मीन पर खड़ा व्यक्ति मुक्त पतन में नहीं है — ज़मीन उसके वज़न के बराबर normal बल से वापस धक्का देती है, तो वह अपना पूरा वज़न महसूस करता है, भारहीनता नहीं।"},
    tags:["theory"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q125", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-10", type:"mcq", diff:"hard",
    q:{en:"A very large, cylindrical space station (far bigger than the ISS) is orbiting Earth. An astronaut lies with their head near the station's inner-facing wall and feet extending well beyond a kilometre further out. Would they feel completely weightless, exactly like an ISS astronaut?", hi:"पृथ्वी की परिक्रमा करता एक बहुत बड़ा, बेलनाकार अंतरिक्ष स्टेशन (ISS से कहीं बड़ा) है। एक अंतरिक्ष यात्री का सिर स्टेशन की भीतरी दीवार के पास है और पैर एक किलोमीटर से ज़्यादा दूर तक फैले हैं। क्या वह ISS के अंतरिक्ष यात्री जैसी बिलकुल पूरी भारहीनता महसूस करेगा?"},
    opts:{en:["Yes, exactly the same, size never matters for free fall","Not quite — gravity (and so the free-fall acceleration) differs slightly between their head and feet at such a large separation, so a small residual force (a 'tidal' stretch) would be felt, unlike the ISS where the astronaut's whole body free-falls at essentially one rate","No, they would feel their full normal weight","Weightlessness has nothing to do with size at all, so the question is meaningless"],
          hi:["हाँ, बिलकुल वैसे ही, मुक्त पतन के लिए आकार कभी मायने नहीं रखता","पूरी तरह नहीं — इतनी बड़ी दूरी पर सिर और पैर के बीच गुरुत्वाकर्षण (और इसलिए मुक्त-पतन त्वरण) थोड़ा अलग होता है, तो एक छोटा बचा हुआ बल (एक 'ज्वारीय' खिंचाव) महसूस होगा, ISS के उलट जहाँ अंतरिक्ष यात्री का पूरा शरीर लगभग एक ही दर से मुक्त पतन करता है","नहीं, वह अपना पूरा normal वज़न महसूस करेगा","भारहीनता का आकार से कोई लेना-देना नहीं, तो सवाल ही बेमानी है"]},
    correct:"B", exp:{en:"This is a genuine NCERT Points to Ponder extension question. Free fall gives perfect weightlessness only when every part of the body/station falls at essentially the same rate — true for a small spacecraft like the ISS, but a large enough station would show measurable differences in g across its size, producing a small residual (tidal) force.", hi:"यह असली NCERT विचारणीय विषय का विस्तार सवाल है। मुक्त पतन पूरी भारहीनता तभी देता है जब शरीर/स्टेशन का हर हिस्सा लगभग एक ही दर से गिरे — ISS जैसे छोटे यान के लिए सच, पर काफ़ी बड़ा स्टेशन अपने आकार में g का नापने लायक़ फ़र्क़ दिखाएगा, एक छोटा बचा हुआ (ज्वारीय) बल पैदा करते हुए।"},
    tags:["theory","hots"], source:"SelfLearn Physics Ch7, NCERT-aligned", status:"published" },
  { id:"PHY-Q126", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-2", type:"mcq", diff:"hard",
    q:{en:"A rocket is fired from Earth towards the Sun. At what distance from Earth's centre is the gravitational force on it zero? (Mass of Sun = 2×10³⁰ kg, mass of Earth = 6×10²⁴ kg, Earth-Sun distance = 1.5×10¹¹ m.)", hi:"एक रॉकेट पृथ्वी से सूर्य की ओर छोड़ा जाता है। पृथ्वी के केंद्र से कितनी दूरी पर उस पर गुरुत्वीय बल शून्य होगा? (सूर्य का द्रव्यमान = 2×10³⁰ kg, पृथ्वी का द्रव्यमान = 6×10²⁴ kg, पृथ्वी-सूर्य दूरी = 1.5×10¹¹ m।)"},
    opts:{en:["2.6 × 10⁸ m","2.6 × 10⁹ m","1.5 × 10¹⁰ m","6.0 × 10⁷ m"],
          hi:["2.6 × 10⁸ m","2.6 × 10⁹ m","1.5 × 10¹⁰ m","6.0 × 10⁷ m"]},
    correct:"A", exp:{en:"Setting GMEm/x² = GMsm/(r−x)² gives (r−x)/x = √(Ms/ME) = √(2×10³⁰/6×10²⁴) ≈ 577. Solving, x = r/578 ≈ 2.6×10⁸ m from Earth's centre — interestingly close to the Moon's distance.", hi:"GMEm/x² = GMsm/(r−x)² रखने पर (r−x)/x = √(Ms/ME) = √(2×10³⁰/6×10²⁴) ≈ 577। हल करने पर, x = r/578 ≈ 2.6×10⁸ m पृथ्वी के केंद्र से — दिलचस्प रूप से चाँद की दूरी के क़रीब।"},
    tags:["numerical","ncert-exercise","exam-important"], source:"NCERT Exercise 7.12", status:"published" },
  { id:"PHY-Q127", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-1", type:"mcq", diff:"hard",
    q:{en:"A Saturn year is 29.5 times the Earth year. If Earth's orbital radius around the Sun is 1.5×10⁸ km, how far is Saturn from the Sun?", hi:"शनि का वर्ष पृथ्वी के वर्ष से 29.5 गुना है। अगर सूर्य के परित: पृथ्वी की कक्षीय त्रिज्या 1.5×10⁸ km है, तो शनि सूर्य से कितनी दूर है?"},
    opts:{en:["4.4 × 10⁸ km","1.43 × 10⁹ km","2.9 × 10⁹ km","8.85 × 10⁸ km"],
          hi:["4.4 × 10⁸ km","1.43 × 10⁹ km","2.9 × 10⁹ km","8.85 × 10⁸ km"]},
    correct:"B", exp:{en:"By Kepler's third law, R_Saturn = R_Earth × (T_Saturn/T_Earth)^(2/3) = 1.5×10⁸ × (29.5)^(2/3) ≈ 1.5×10⁸ × 9.55 ≈ 1.43×10⁹ km.", hi:"केप्लर के तीसरे नियम से, R_शनि = R_पृथ्वी × (T_शनि/T_पृथ्वी)^(2/3) = 1.5×10⁸ × (29.5)^(2/3) ≈ 1.5×10⁸ × 9.55 ≈ 1.43×10⁹ km।"},
    tags:["numerical","ncert-exercise","exam-important"], source:"NCERT Exercise 7.14", status:"published" },
  { id:"PHY-Q128", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-4", type:"mcq", diff:"medium",
    q:{en:"A body weighs 63 N on Earth's surface. What is the gravitational force on it at a height equal to half of Earth's radius?", hi:"पृथ्वी की सतह पर एक वस्तु का वज़न 63 N है। पृथ्वी की त्रिज्या की आधी ऊँचाई पर उस पर गुरुत्वीय बल क्या है?"},
    opts:{en:["31.5 N","28 N","42 N","56 N"],
          hi:["31.5 N","28 N","42 N","56 N"]},
    correct:"B", exp:{en:"g(h) = g/(1+h/RE)² = g/(1.5)² = g/2.25. Weight = 63/2.25 = 28 N.", hi:"g(h) = g/(1+h/RE)² = g/(1.5)² = g/2.25। वज़न = 63/2.25 = 28 N।"},
    tags:["numerical","ncert-exercise","exam-important"], source:"NCERT Exercise 7.15", status:"published" },
  { id:"PHY-Q129", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-4", type:"mcq", diff:"medium",
    q:{en:"A body weighs 250 N on Earth's surface. How much would it weigh halfway down to the centre of the Earth?", hi:"पृथ्वी की सतह पर एक वस्तु का वज़न 250 N है। पृथ्वी के केंद्र तक आधे रास्ते पर उसका वज़न कितना होगा?"},
    opts:{en:["250 N","187.5 N","125 N","62.5 N"],
          hi:["250 N","187.5 N","125 N","62.5 N"]},
    correct:"C", exp:{en:"g(d) = g(1 − d/RE) = g(1 − 0.5) = 0.5g. Weight = 250 × 0.5 = 125 N.", hi:"g(d) = g(1 − d/RE) = g(1 − 0.5) = 0.5g। वज़न = 250 × 0.5 = 125 N।"},
    tags:["numerical","ncert-exercise","exam-important"], source:"NCERT Exercise 7.16", status:"published" },
  { id:"PHY-Q130", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-5", type:"mcq", diff:"hard",
    q:{en:"A rocket is fired vertically with a speed of 5 km/s from Earth's surface. How far from the centre of the Earth does it go before returning? (RE = 6.4×10⁶ m, ME = 6.0×10²⁴ kg, G = 6.67×10⁻¹¹ N m² kg⁻².)", hi:"एक रॉकेट पृथ्वी की सतह से 5 km/s की speed से सीधा ऊपर छोड़ा जाता है। वापस आने से पहले वह पृथ्वी के केंद्र से कितनी दूर जाता है? (RE = 6.4×10⁶ m, ME = 6.0×10²⁴ kg, G = 6.67×10⁻¹¹ N m² kg⁻²।)"},
    opts:{en:["≈ 6.4 × 10⁶ m (no real height gained)","≈ 8.0 × 10⁶ m","≈ 1.6 × 10⁷ m","≈ 3.84 × 10⁸ m (reaches the Moon)"],
          hi:["≈ 6.4 × 10⁶ m (कोई असली ऊँचाई नहीं)","≈ 8.0 × 10⁶ m","≈ 1.6 × 10⁷ m","≈ 3.84 × 10⁸ m (चाँद तक पहुँचता है)"]},
    correct:"B", exp:{en:"Using energy conservation, ½v² − GME/RE = −GME/r_max. Solving gives r_max ≈ 8.0×10⁶ m from Earth's centre, i.e. a height of about 1.6×10⁶ m (1600 km) above the surface.", hi:"ऊर्जा संरक्षण का इस्तेमाल करते हुए, ½v² − GME/RE = −GME/r_max। हल करने पर r_max ≈ 8.0×10⁶ m पृथ्वी के केंद्र से, यानी सतह से लगभग 1.6×10⁶ m (1600 km) ऊँचाई।"},
    tags:["numerical","ncert-exercise","hots","exam-important"], source:"NCERT Exercise 7.17", status:"published" },
  { id:"PHY-Q131", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-6", type:"mcq", diff:"medium",
    q:{en:"The escape speed of a projectile from Earth's surface is 11.2 km/s. A body is projected out with thrice this speed. What is its speed far away from Earth? (Ignore the Sun and other planets.)", hi:"पृथ्वी की सतह से किसी प्रक्षेप्य की पलायन चाल 11.2 km/s है। एक वस्तु इस speed की तीन गुनी speed से बाहर छोड़ी जाती है। पृथ्वी से बहुत दूर उसकी speed क्या है? (सूर्य और अन्य ग्रहों को नज़रअंदाज़ कीजिए।)"},
    opts:{en:["11.2 km/s","22.4 km/s","31.7 km/s","33.6 km/s"],
          hi:["11.2 km/s","22.4 km/s","31.7 km/s","33.6 km/s"]},
    correct:"C", exp:{en:"v_far² = v_i² − vₑ² = (3vₑ)² − vₑ² = 8vₑ². v_far = vₑ√8 = 2√2 × 11.2 ≈ 31.7 km/s.", hi:"v_दूर² = v_i² − vₑ² = (3vₑ)² − vₑ² = 8vₑ²। v_दूर = vₑ√8 = 2√2 × 11.2 ≈ 31.7 km/s।"},
    tags:["numerical","ncert-exercise","exam-important"], source:"NCERT Exercise 7.18", status:"published" },
  { id:"PHY-Q132", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-9", type:"mcq", diff:"hard",
    q:{en:"A satellite orbits Earth at a height of 400 km. Mass of satellite = 200 kg, mass of Earth = 6.0×10²⁴ kg, radius of Earth = 6.4×10⁶ m, G = 6.67×10⁻¹¹ N m² kg⁻². How much energy must be spent to rocket the satellite out of Earth's gravitational influence?", hi:"एक उपग्रह पृथ्वी की परिक्रमा 400 km ऊँचाई पर करता है। उपग्रह का द्रव्यमान = 200 kg, पृथ्वी का द्रव्यमान = 6.0×10²⁴ kg, पृथ्वी की त्रिज्या = 6.4×10⁶ m, G = 6.67×10⁻¹¹ N m² kg⁻²। उपग्रह को पृथ्वी के गुरुत्वीय प्रभाव से बाहर भेजने में कितनी ऊर्जा ख़र्च करनी होगी?"},
    opts:{en:["≈ 5.9 × 10⁹ J","≈ 2.9 × 10⁹ J","≈ 1.2 × 10¹⁰ J","≈ 5.9 × 10⁶ J"],
          hi:["≈ 5.9 × 10⁹ J","≈ 2.9 × 10⁹ J","≈ 1.2 × 10¹⁰ J","≈ 5.9 × 10⁶ J"]},
    correct:"A", exp:{en:"Energy needed = 0 − E_orbit = GMEm/2r, where r = RE+h = 6.8×10⁶ m. GMEm/2r = (6.67×10⁻¹¹ × 6×10²⁴ × 200) / (2 × 6.8×10⁶) ≈ 5.9×10⁹ J.", hi:"ज़रूरी ऊर्जा = 0 − E_कक्षा = GMEm/2r, जहाँ r = RE+h = 6.8×10⁶ m। GMEm/2r = (6.67×10⁻¹¹ × 6×10²⁴ × 200) / (2 × 6.8×10⁶) ≈ 5.9×10⁹ J।"},
    tags:["numerical","ncert-exercise","hots","exam-important"], source:"NCERT Exercise 7.19", status:"published" },
  { id:"PHY-Q133", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-5", type:"mcq", diff:"hard",
    q:{en:"Two heavy spheres, each of mass 100 kg and radius 0.10 m, are placed 1.0 m apart (centre to centre). What can be said about an object placed exactly at the midpoint of the line joining their centres?", hi:"दो भारी गोले, हर एक 100 kg द्रव्यमान और 0.10 m त्रिज्या के, 1.0 m दूर (केंद्र से केंद्र) रखे हैं। उनके केंद्रों को जोड़ने वाली रेखा के ठीक मध्यबिंदु पर रखी वस्तु के बारे में क्या कहा जा सकता है?"},
    opts:{en:["Force is zero, potential is zero, equilibrium is stable","Force is zero, potential is not zero, and the equilibrium is unstable","Force is not zero, so there is no equilibrium at all","Force and potential are both non-zero, equilibrium is stable"],
          hi:["बल शून्य है, विभव शून्य है, संतुलन स्थिर है","बल शून्य है, विभव शून्य नहीं है, और संतुलन अस्थिर है","बल शून्य नहीं है, तो कोई संतुलन ही नहीं है","बल और विभव दोनों शून्य नहीं, संतुलन स्थिर है"]},
    correct:"B", exp:{en:"By symmetry, the pulls from both equal spheres, at equal distance (0.5 m each), exactly cancel, so force = 0 — the object is in equilibrium. But potential U = −2×G×100/0.5 ≈ −2.7×10⁻⁸ J/kg is not zero. Any small displacement along the joining line brings the object closer to one sphere, whose stronger pull then dominates and pulls it further off-centre — the equilibrium is unstable.", hi:"सममिति से, दोनों बराबर गोलों के खिंचाव, बराबर दूरी (0.5 m हर एक) पर, बिलकुल कट जाते हैं, तो बल = 0 — वस्तु संतुलन में है। पर विभव U = −2×G×100/0.5 ≈ −2.7×10⁻⁸ J/kg शून्य नहीं है। जोड़ने वाली रेखा पर कोई छोटा विस्थापन वस्तु को एक गोले के पास ले जाता है, जिसका मज़बूत खिंचाव फिर हावी होकर उसे और केंद्र से दूर खींचता है — संतुलन अस्थिर है।"},
    tags:["numerical","ncert-exercise","hots","exam-important"], source:"NCERT Exercise 7.21", status:"published" },
  { id:"PHY-Q134", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-4", type:"mcq", diff:"medium",
    q:{en:"Taking g = 9.8 m/s² and RE = 6400 km, find g at a height of 300 km above Earth's surface.", hi:"g = 9.8 m/s² और RE = 6400 km मानते हुए, पृथ्वी की सतह से 300 km ऊँचाई पर g निकालिए।"},
    opts:{en:["9.8 m/s²","8.88 m/s²","7.20 m/s²","9.34 m/s²"],
          hi:["9.8 m/s²","8.88 m/s²","7.20 m/s²","9.34 m/s²"]},
    correct:"B", exp:{en:"g(h) ≈ g(1 − 2h/RE) = 9.8 × (1 − 2×300/6400) = 9.8 × 0.90625 ≈ 8.88 m/s².", hi:"g(h) ≈ g(1 − 2h/RE) = 9.8 × (1 − 2×300/6400) = 9.8 × 0.90625 ≈ 8.88 m/s²।"},
    tags:["numerical","board-pattern"], source:"Board-pattern numerical", status:"published" },
  { id:"PHY-Q135", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-2", type:"mcq", diff:"easy",
    q:{en:"Find the gravitational force between two masses of 5 kg and 10 kg placed 2 m apart. (G = 6.67×10⁻¹¹ N m² kg⁻².)", hi:"2 m दूर रखे 5 kg और 10 kg के दो द्रव्यमानों के बीच गुरुत्वीय बल निकालिए। (G = 6.67×10⁻¹¹ N m² kg⁻²।)"},
    opts:{en:["8.34 × 10⁻¹⁰ N","1.67 × 10⁻⁹ N","3.34 × 10⁻¹⁰ N","6.67 × 10⁻¹⁰ N"],
          hi:["8.34 × 10⁻¹⁰ N","1.67 × 10⁻⁹ N","3.34 × 10⁻¹⁰ N","6.67 × 10⁻¹⁰ N"]},
    correct:"A", exp:{en:"F = G m1m2/r² = 6.67×10⁻¹¹ × 5 × 10 / 4 = 6.67×10⁻¹¹ × 12.5 ≈ 8.34×10⁻¹⁰ N.", hi:"F = G m1m2/r² = 6.67×10⁻¹¹ × 5 × 10 / 4 = 6.67×10⁻¹¹ × 12.5 ≈ 8.34×10⁻¹⁰ N।"},
    tags:["numerical","board-pattern"], source:"Board-pattern numerical", status:"published" },
  { id:"PHY-Q136", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-7", type:"mcq", diff:"medium",
    q:{en:"A satellite orbits Earth at a height where the orbital radius is 1.0×10⁷ m. Taking GME = 3.98×10¹⁴ m³/s², find its orbital period.", hi:"एक उपग्रह पृथ्वी की परिक्रमा उस ऊँचाई पर करता है जहाँ कक्षीय त्रिज्या 1.0×10⁷ m है। GME = 3.98×10¹⁴ m³/s² मानते हुए, उसका कक्षीय आवर्तकाल निकालिए।"},
    opts:{en:["≈ 85 minutes","≈ 166 minutes","≈ 24 hours","≈ 12 hours"],
          hi:["≈ 85 मिनट","≈ 166 मिनट","≈ 24 घंटे","≈ 12 घंटे"]},
    correct:"B", exp:{en:"T = 2π√(r³/GME) = 2π√(10²¹/3.98×10¹⁴) = 2π√(2.51×10⁶) ≈ 2π×1585 ≈ 9960 s ≈ 166 minutes.", hi:"T = 2π√(r³/GME) = 2π√(10²¹/3.98×10¹⁴) = 2π√(2.51×10⁶) ≈ 2π×1585 ≈ 9960 s ≈ 166 मिनट।"},
    tags:["numerical","board-pattern"], source:"Board-pattern numerical", status:"published" },
  { id:"PHY-Q137", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-4", type:"mcq", diff:"easy",
    q:{en:"A person weighs 490 N (mass 50 kg) at sea level. Approximately how much do they weigh atop a 5 km mountain? (RE = 6400 km.)", hi:"समुद्र तल पर एक व्यक्ति का वज़न 490 N (द्रव्यमान 50 kg) है। 5 km ऊँचे पहाड़ की चोटी पर उसका वज़न लगभग कितना होगा? (RE = 6400 km।)"},
    opts:{en:["490 N (no change)","489.2 N","485 N","470 N"],
          hi:["490 N (कोई बदलाव नहीं)","489.2 N","485 N","470 N"]},
    correct:"B", exp:{en:"g(h) ≈ g(1 − 2h/RE) = 9.8 × (1 − 2×5/6400) = 9.8 × 0.9984 ≈ 9.784 m/s². Weight = 50 × 9.784 ≈ 489.2 N — a very small but real decrease.", hi:"g(h) ≈ g(1 − 2h/RE) = 9.8 × (1 − 2×5/6400) = 9.8 × 0.9984 ≈ 9.784 m/s²। वज़न = 50 × 9.784 ≈ 489.2 N — बहुत छोटी पर असली कमी।"},
    tags:["numerical","board-pattern"], source:"Board-pattern numerical", status:"published" },
  { id:"PHY-Q138", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-5", type:"mcq", diff:"medium",
    q:{en:"How much work is done in raising a 10 kg mass from Earth's surface to a height of 2RE (i.e., to r = 3RE from the centre)? (GME = 3.98×10¹⁴ m³/s², RE = 6.4×10⁶ m.)", hi:"10 kg के द्रव्यमान को पृथ्वी की सतह से 2RE ऊँचाई तक (यानी केंद्र से r = 3RE तक) उठाने में कितना काम लगता है? (GME = 3.98×10¹⁴ m³/s², RE = 6.4×10⁶ m।)"},
    opts:{en:["≈ 6.2 × 10⁸ J","≈ 4.1 × 10⁸ J","≈ 2.1 × 10⁸ J","≈ 8.3 × 10⁸ J"],
          hi:["≈ 6.2 × 10⁸ J","≈ 4.1 × 10⁸ J","≈ 2.1 × 10⁸ J","≈ 8.3 × 10⁸ J"]},
    correct:"B", exp:{en:"W = V(3RE) − V(RE) = −GMEm/3RE − (−GMEm/RE) = GMEm(1 − 1/3)/RE = (2/3)×GMEm/RE. GMEm/RE = 3.98×10¹⁴×10/6.4×10⁶ ≈ 6.22×10⁸ J. W = (2/3)×6.22×10⁸ ≈ 4.1×10⁸ J.", hi:"W = V(3RE) − V(RE) = −GMEm/3RE − (−GMEm/RE) = GMEm(1 − 1/3)/RE = (2/3)×GMEm/RE। GMEm/RE = 3.98×10¹⁴×10/6.4×10⁶ ≈ 6.22×10⁸ J। W = (2/3)×6.22×10⁸ ≈ 4.1×10⁸ J।"},
    tags:["numerical","board-pattern"], source:"Board-pattern numerical", status:"published" },
  { id:"PHY-Q139", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-6", type:"mcq", diff:"medium",
    q:{en:"A hypothetical planet has 4 times Earth's mass and twice Earth's radius. What is its escape speed compared to Earth's (vₑ = 11.2 km/s)?", hi:"एक काल्पनिक ग्रह का द्रव्यमान पृथ्वी से 4 गुना और त्रिज्या पृथ्वी से दुगनी है। पृथ्वी की पलायन चाल (vₑ = 11.2 km/s) के मुक़ाबले उसकी पलायन चाल क्या है?"},
    opts:{en:["Same as Earth's, 11.2 km/s","√2 times Earth's, ≈ 15.8 km/s","2 times Earth's, 22.4 km/s","Half of Earth's, 5.6 km/s"],
          hi:["पृथ्वी जैसी ही, 11.2 km/s","पृथ्वी की √2 गुनी, ≈ 15.8 km/s","पृथ्वी की 2 गुनी, 22.4 km/s","पृथ्वी की आधी, 5.6 km/s"]},
    correct:"B", exp:{en:"v' = √(2G(4ME)/(2RE)) = √(4 × GME/RE) = 2√(GME/RE). Earth's vₑ = √(2GME/RE). Ratio v'/vₑ = 2/√2 = √2. So v' ≈ 1.41 × 11.2 ≈ 15.8 km/s.", hi:"v' = √(2G(4ME)/(2RE)) = √(4 × GME/RE) = 2√(GME/RE)। पृथ्वी की vₑ = √(2GME/RE)। अनुपात v'/vₑ = 2/√2 = √2। तो v' ≈ 1.41 × 11.2 ≈ 15.8 km/s।"},
    tags:["numerical","board-pattern","exam-important"], source:"Board-pattern numerical", status:"published" },
  { id:"PHY-Q140", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-1", type:"mcq", diff:"hard",
    q:{en:"Two stars, each of mass 3×10³⁰ kg, orbit their common centre of mass, separated by a fixed distance of 2×10¹¹ m. Find their orbital period.", hi:"दो तारे, हर एक 3×10³⁰ kg द्रव्यमान के, अपने साझा द्रव्यमान केंद्र की परिक्रमा करते हैं, 2×10¹¹ m की तय दूरी पर। उनका कक्षीय आवर्तकाल निकालिए।"},
    opts:{en:["≈ 2.8 × 10⁷ s (≈ 325 days)","≈ 8.5 × 10⁶ s (≈ 100 days)","≈ 5.6 × 10⁷ s (≈ 650 days)","≈ 3.15 × 10⁷ s (1 year)"],
          hi:["≈ 2.8 × 10⁷ s (≈ 325 दिन)","≈ 8.5 × 10⁶ s (≈ 100 दिन)","≈ 5.6 × 10⁷ s (≈ 650 दिन)","≈ 3.15 × 10⁷ s (1 वर्ष)"]},
    correct:"A", exp:{en:"Each star orbits at radius d/2 about the COM. Gravity supplies centripetal force: GM²/d² = Mω²(d/2), so ω² = 2GM/d³ = 2×6.67×10⁻¹¹×3×10³⁰/(2×10¹¹)³ ≈ 5.0×10⁻¹⁴. ω ≈ 2.24×10⁻⁷ rad/s. T = 2π/ω ≈ 2.8×10⁷ s ≈ 325 days.", hi:"हर तारा COM के परित: d/2 त्रिज्या पर परिक्रमा करता है। गुरुत्वाकर्षण अभिकेन्द्र बल देता है: GM²/d² = Mω²(d/2), तो ω² = 2GM/d³ = 2×6.67×10⁻¹¹×3×10³⁰/(2×10¹¹)³ ≈ 5.0×10⁻¹⁴। ω ≈ 2.24×10⁻⁷ rad/s। T = 2π/ω ≈ 2.8×10⁷ s ≈ 325 दिन।"},
    tags:["numerical","jee-pattern","hots"], source:"JEE-pattern numerical (binary star system)", status:"published" },
  { id:"PHY-Q141", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-9", type:"mcq", diff:"hard",
    q:{en:"Two satellites of mass m and 2m are both in the same circular orbit of radius r around Earth. Compare their orbital speeds, periods, and total energies.", hi:"m और 2m द्रव्यमान के दो उपग्रह पृथ्वी के परित: एक ही r त्रिज्या की वृत्तीय कक्षा में हैं। उनकी कक्षीय speed, आवर्तकाल और कुल ऊर्जा की तुलना कीजिए।"},
    opts:{en:["Same speed, same period, but the 2m satellite has twice the magnitude of total energy","2m satellite has twice the speed and half the period, same energy","Both differ in speed, period, and energy by a factor of 2","2m satellite has half the speed, same period, half the energy"],
          hi:["एक जैसी speed, एक जैसा आवर्तकाल, पर 2m उपग्रह की कुल ऊर्जा का परिमाण दुगना","2m उपग्रह की speed दुगनी और आवर्तकाल आधा, ऊर्जा एक जैसी","speed, आवर्तकाल, और ऊर्जा तीनों 2 के गुणक से अलग","2m उपग्रह की speed आधी, आवर्तकाल एक जैसा, ऊर्जा आधी"]},
    correct:"A", exp:{en:"V = √(GM/r) and T = 2π√(r³/GM) — neither depends on the satellite's own mass, so both satellites have identical speed and period. But E = −GMm/2r scales directly with m, so the 2m satellite's total energy has twice the magnitude (more negative).", hi:"V = √(GM/r) और T = 2π√(r³/GM) — दोनों में उपग्रह के अपने द्रव्यमान का कोई पद नहीं, तो दोनों उपग्रहों की speed और आवर्तकाल एक जैसे हैं। पर E = −GMm/2r सीधे m के साथ बदलता है, तो 2m उपग्रह की कुल ऊर्जा का परिमाण दुगना है (ज़्यादा ऋणात्मक)।"},
    tags:["theory","jee-pattern","hots","exam-important"], source:"JEE-pattern conceptual numerical", status:"published" },
  { id:"PHY-Q142", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-9", type:"mcq", diff:"hard",
    q:{en:"At any orbital radius r around Earth, how does the escape speed from that point compare to the circular orbital speed at that same point?", hi:"पृथ्वी के परित: किसी भी कक्षीय त्रिज्या r पर, उस बिंदु से पलायन चाल, उसी बिंदु की वृत्तीय कक्षीय speed से कैसे तुलना करती है?"},
    opts:{en:["Escape speed = orbital speed","Escape speed = √2 × orbital speed, always, at every radius","Escape speed = 2 × orbital speed","The relationship depends on r and cannot be stated generally"],
          hi:["पलायन चाल = कक्षीय speed","पलायन चाल = √2 × कक्षीय speed, हमेशा, हर त्रिज्या पर","पलायन चाल = 2 × कक्षीय speed","यह रिश्ता r पर निर्भर करता है, सामान्य रूप से नहीं बताया जा सकता"]},
    correct:"B", exp:{en:"v_esc(r) = √(2GM/r) and V_orbit(r) = √(GM/r). Their ratio is √2 for every r — this is a general result, not specific to any one orbit, and a favourite JEE fact to quote directly.", hi:"v_पलायन(r) = √(2GM/r) और V_कक्षीय(r) = √(GM/r)। उनका अनुपात हर r के लिए √2 है — यह एक सामान्य नतीजा है, किसी एक कक्षा तक सीमित नहीं, और सीधे उद्धृत करने के लिए एक पसंदीदा JEE तथ्य है।"},
    tags:["theory","jee-pattern","hots","exam-important"], source:"JEE-pattern derivation-based numerical", status:"published" },
  { id:"PHY-Q143", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-4", type:"mcq", diff:"hard",
    q:{en:"A frictionless tunnel is drilled straight through the Earth's centre, and a ball is dropped into it. Assuming Earth has uniform density, what kind of motion does the ball perform, and what is its time period?", hi:"पृथ्वी के केंद्र से सीधे एक घर्षण-रहित सुरंग खोदी जाती है, और उसमें एक गेंद गिराई जाती है। पृथ्वी को एकसमान घनत्व मानते हुए, गेंद कैसी गति करती है, और उसका आवर्तकाल क्या है?"},
    opts:{en:["Uniform circular motion, period 24 hours","Simple harmonic motion, with time period T = 2π√(RE/g), the same ≈ 85 minutes as a satellite skimming the surface","The ball accelerates forever and never returns","Simple harmonic motion, but the period cannot be found without knowing the tunnel's length"],
          hi:["एकसमान वृत्तीय गति, आवर्तकाल 24 घंटे","सरल आवर्त गति (SHM), समय अवधि T = 2π√(RE/g) के साथ, ठीक वही ≈ 85 मिनट जो सतह के पास सरकते उपग्रह का है","गेंद हमेशा त्वरित होती रहती है और कभी वापस नहीं आती","सरल आवर्त गति, पर सुरंग की लंबाई जाने बिना आवर्तकाल नहीं निकाला जा सकता"]},
    correct:"B", exp:{en:"Inside a uniform Earth at distance r from the centre, g(r) = g×(r/RE), so the restoring force F = −mg(r/RE) is exactly SHM's F = −kx form with k = mg/RE. This gives ω = √(g/RE) and T = 2π√(RE/g) — algebraically identical to T₀, the period of a satellite skimming just above the surface, a genuinely surprising connection between two very different-looking problems.", hi:"एकसमान पृथ्वी के भीतर केंद्र से दूरी r पर, g(r) = g×(r/RE), तो restoring बल F = −mg(r/RE) बिलकुल SHM के F = −kx रूप जैसा है, k = mg/RE के साथ। इससे ω = √(g/RE) और T = 2π√(RE/g) मिलता है — बीजगणितीय रूप से बिलकुल T₀ जैसा, सतह के ठीक ऊपर सरकते उपग्रह का आवर्तकाल, दो बिलकुल अलग दिखने वाले सवालों के बीच एक सचमुच हैरान करने वाला रिश्ता।"},
    tags:["theory","numerical","jee-pattern","hots"], source:"JEE-pattern derivation-based conceptual question", status:"published" },
  { id:"PHY-Q144", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-2", type:"mcq", diff:"hard",
    q:{en:"A thin uniform ring of mass M and radius R is fixed. A small mass m is placed on the ring's axis, at a distance R from the centre (i.e., at 45° from the plane, since the distance to any point on the ring is R√2). Which statement about the net gravitational force on m is correct?", hi:"द्रव्यमान M और त्रिज्या R का एक पतला एकसमान वलय स्थिर है। एक छोटा द्रव्यमान m वलय की अक्ष पर, केंद्र से R दूरी पर रखा है (यानी तल से 45° पर, क्योंकि वलय के किसी भी बिंदु की दूरी R√2 है)। m पर शुद्ध गुरुत्वीय बल के बारे में कौन-सा कथन सही है?"},
    opts:{en:["Zero, by symmetry of the ring","Non-zero, directed along the axis towards the ring's centre, since the sideways components from every point of the ring cancel by symmetry but the axial components add","Non-zero, directed away from the ring","Cannot be determined without calculus, no shortcut exists"],
          hi:["वलय की सममिति से शून्य","शून्य नहीं, अक्ष के साथ वलय के केंद्र की ओर, क्योंकि वलय के हर बिंदु से आने वाले बग़ल के घटक सममिति से कट जाते हैं पर अक्षीय घटक जुड़ते हैं","शून्य नहीं, वलय से दूर की ओर","calculus के बिना तय नहीं किया जा सकता, कोई शॉर्टकट नहीं"]},
    correct:"B", exp:{en:"Every point of the ring pulls m along a line making the same angle with the axis. By symmetry, all sideways (radial) components cancel around the ring, leaving only the axial components, which all add constructively — giving a net pull along the axis, towards the ring, not zero.", hi:"वलय का हर बिंदु m को एक ऐसी रेखा के साथ खींचता है जो अक्ष से वही कोण बनाती है। सममिति से, वलय के चारों ओर सारे बग़ल (त्रिज्यीय) घटक कट जाते हैं, सिर्फ़ अक्षीय घटक बचते हैं, जो सब मिलकर जुड़ते हैं — अक्ष के साथ, वलय की ओर, एक शुद्ध खिंचाव देते हुए, शून्य नहीं।"},
    tags:["theory","jee-pattern","hots"], source:"JEE-pattern conceptual (superposition + symmetry)", status:"published" },
  { id:"PHY-Q145", board:"CBSE", klass:"11", subject:"PHY", chapter:7, topic:"PHY-7-6", type:"mcq", diff:"hard",
    q:{en:"A planet has the same mean density as Earth but a radius three times Earth's. How does its escape speed compare to Earth's?", hi:"एक ग्रह का औसत घनत्व पृथ्वी जैसा है, पर त्रिज्या पृथ्वी से तीन गुनी है। उसकी पलायन चाल पृथ्वी से कैसे तुलना करती है?"},
    opts:{en:["Same as Earth's","3 times Earth's","√3 times Earth's","9 times Earth's"],
          hi:["पृथ्वी जैसी ही","पृथ्वी की 3 गुनी","पृथ्वी की √3 गुनी","पृथ्वी की 9 गुनी"]},
    correct:"B", exp:{en:"Since mass M ∝ ρR³ and density ρ is the same, M' = 27ME for R' = 3RE. vₑ = √(2GM/R), so vₑ' /vₑ = √(M'/ME × RE/R') = √(27/3) = √9 = 3. Escape speed scales directly with radius when density is held fixed.", hi:"चूँकि द्रव्यमान M ∝ ρR³ और घनत्व ρ वही है, R' = 3RE के लिए M' = 27ME। vₑ = √(2GM/R), तो vₑ'/vₑ = √(M'/ME × RE/R') = √(27/3) = √9 = 3। घनत्व स्थिर रहने पर पलायन चाल सीधे त्रिज्या के साथ बदलती है।"},
    tags:["numerical","jee-pattern","hots"], source:"JEE-pattern numerical (density-scaling)", status:"published" }
);
